PROVIDER_MODES = {"native_rank_fusion", "native_score_fusion", "application_rrf"}
TECHNICAL_STATUSES = {"metadata_only", "ports_extracted", "flow_graph_extracted", "verified_runtime"}
MAX_QUERY_COUNT = 30
