def _safe_identifier(value: Any, default: str) -> str:
    text = str(value or default).strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", text):
        raise ValueError("INVALID_PROVIDER_IDENTIFIER")
    return text


def _payload(value: Any) -> Any:
    if isinstance(value, (dict, list)):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, (dict, list)):
        return data
    if isinstance(value, str) and value.strip():
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            return {}
    return {}


def _secret(value: Any) -> str:
    getter = getattr(value, "get_secret_value", None)
    if callable(getter):
        return str(getter())
    return str(value or "")


def _canonical_hash(value: Any) -> str:
    material = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(material.encode("utf-8")).hexdigest()


def _string_list(value: Any, maximum: int = 100) -> list[str]:
    if isinstance(value, str):
        source = re.split(r"[,;\n]", value)
    elif isinstance(value, (list, tuple, set)):
        source = list(value)
    else:
        source = []
    result: list[str] = []
    for item in source[:maximum]:
        text = str(item or "").strip()
        if text and text not in result:
            result.append(text)
    return result


def _normalize_exact_key(value: Any) -> str:
    text = unicodedata.normalize("NFKC", str(value or "")).casefold().strip()
    return re.sub(r"\s+", " ", text)[:500]


def _acl_filter(tenant_id: str, acl: dict[str, Any]) -> dict[str, Any]:
    groups = [item.lower() for item in _string_list(acl.get("groups"))]
    subject_id = str(acl.get("subject_id") or "")
    choices: list[dict[str, Any]] = [{"acl.visibility": "tenant"}]
    if groups:
        choices.append({"acl.visibility": "group", "acl.groups": {"$in": groups}})
    if subject_id:
        choices.append({"acl.visibility": "private", "acl.subjects": subject_id})
    return {"tenant_id": tenant_id, "$or": choices}


def _acl_allows(document: dict[str, Any], tenant_id: str, snapshot_id: str, acl: dict[str, Any]) -> bool:
    if str(document.get("tenant_id") or "") != tenant_id:
        return False
    if str(document.get("snapshot_id") or "") != snapshot_id:
        return False
    document_acl = document.get("acl") if isinstance(document.get("acl"), dict) else None
    if document_acl is None:
        return False
    visibility = str(document_acl.get("visibility") or "").lower()
    groups = {item.lower() for item in _string_list(acl.get("groups"))}
    allowed_groups = {item.lower() for item in _string_list(document_acl.get("groups"))}
    subjects = set(_string_list(document_acl.get("subjects")))
    subject_id = str(acl.get("subject_id") or "")
    if visibility == "tenant":
        return True
    if visibility == "group":
        return bool(groups & allowed_groups)
    return visibility == "private" and bool(subject_id) and subject_id in subjects


def _query_vectors(value: Any) -> tuple[dict[str, list[float]], dict[str, Any]]:
    payload = _payload(value)
    contract = payload.get("embedding_contract") if isinstance(payload.get("embedding_contract"), dict) else {}
    declared_dimension = contract.get("dimension")
    if isinstance(declared_dimension, bool) or not isinstance(declared_dimension, int) or not 1 <= declared_dimension <= 8192:
        raise ValueError("VECTOR_CONTRACT_DIMENSION_INVALID")
    raw = payload.get("vectors") if isinstance(payload, dict) else None
    result: dict[str, list[float]] = {}
    if isinstance(raw, dict):
        pairs = raw.items()
    elif isinstance(raw, list):
        pairs = ((item.get("query_id"), item.get("vector")) for item in raw if isinstance(item, dict))
    else:
        pairs = []
    dimension: int | None = None
    for query_id, vector in pairs:
        if not query_id or not isinstance(vector, list) or not vector or len(vector) > 8192:
            raise ValueError("VECTOR_PAYLOAD_INVALID")
        if any(isinstance(item, bool) or not isinstance(item, (int, float)) for item in vector):
            raise ValueError("VECTOR_NUMERIC_INVALID")
        values = [float(item) for item in vector]
        if not all(math.isfinite(item) for item in values):
            raise ValueError("VECTOR_NUMERIC_INVALID")
        if dimension is None:
            dimension = len(values)
        if len(values) != dimension or len(values) != declared_dimension:
            raise ValueError("VECTOR_DIMENSION_MISMATCH")
        result[str(query_id)] = values
    return result, contract


def _mongo_base_filter(tenant_id: str, snapshot_id: str, acl: dict[str, Any], asset_types: list[str]) -> dict[str, Any]:
    base = _acl_filter(tenant_id, acl)
    base["snapshot_id"] = snapshot_id
    if asset_types:
        base["asset_type"] = {"$in": asset_types}
    return base


def _search_filter_clauses(tenant_id: str, snapshot_id: str, acl: dict[str, Any], asset_types: list[str]) -> list[dict[str, Any]]:
    clauses: list[dict[str, Any]] = [
        {"equals": {"path": "tenant_id", "value": tenant_id}},
        {"equals": {"path": "snapshot_id", "value": snapshot_id}},
    ]
    if asset_types:
        clauses.append({"in": {"path": "asset_type", "value": asset_types}})
    # Atlas Search must apply authorization before producing candidates.  This
    # compound clause mirrors the post-query fail-closed ACL verification.
    should: list[dict[str, Any]] = [
        {
            "compound": {
                "must": [{"equals": {"path": "acl.visibility", "value": "tenant"}}]
            }
        }
    ]
    groups = [item.lower() for item in _string_list(acl.get("groups"))]
    if groups:
        should.append(
            {
                "compound": {
                    "must": [
                        {"equals": {"path": "acl.visibility", "value": "group"}},
                        {"in": {"path": "acl.groups", "value": groups}},
                    ]
                }
            }
        )
    subject_id = str(acl.get("subject_id") or "")
    if subject_id:
        should.append(
            {
                "compound": {
                    "must": [
                        {"equals": {"path": "acl.visibility", "value": "private"}},
                        {"equals": {"path": "acl.subjects", "value": subject_id}},
                    ]
                }
            }
        )
    clauses.append({"compound": {"should": should, "minimumShouldMatch": 1}})
    return clauses


def _clean_document(document: dict[str, Any], source: str, rank: int, query_ids: list[str]) -> dict[str, Any]:
    technical = document.get("technical_contract") if isinstance(document.get("technical_contract"), dict) else {}
    technical_status = str(document.get("technical_contract_status") or technical.get("status") or "metadata_only")
    if technical_status not in TECHNICAL_STATUSES:
        technical_status = "metadata_only"
    ports = document.get("ports") if isinstance(document.get("ports"), dict) else {
        "inputs": technical.get("inputs") if isinstance(technical.get("inputs"), list) else [],
        "outputs": technical.get("outputs") if isinstance(technical.get("outputs"), list) else [],
    }
    popularity = document.get("popularity") if isinstance(document.get("popularity"), dict) else {}
    return {
        "asset_id": str(document.get("asset_id") or document.get("id") or "")[:200],
        "version": str(document.get("version") or "")[:100],
        "asset_type": str(document.get("asset_type") or document.get("type") or "")[:50],
        "title": str(document.get("title") or "")[:500],
        "description": str(document.get("description") or "")[:2000],
        "category": str(document.get("category") or "")[:200],
        "readme": str(document.get("readme") or document.get("lexical_text_redacted") or "")[:8000],
        "technical_contract_status": technical_status,
        "ports": ports,
        "relations": document.get("relations") if isinstance(document.get("relations"), list) else [],
        "tenant_id": str(document.get("tenant_id") or ""),
        "snapshot_id": str(document.get("snapshot_id") or ""),
        "acl": document.get("acl") if isinstance(document.get("acl"), dict) else {},
        "stars_count": int(document.get("stars_count") or popularity.get("stars") or 0),
        "downloads_count": int(document.get("downloads_count") or popularity.get("downloads") or 0),
        "updated_at": str(document.get("updated_at") or ""),
        "matched_chunk_id": str(document.get("chunk_id") or "")[:200],
        "source": source,
        "source_rank": rank,
        "query_ids": query_ids,
    }


def _enrich_source_results(
    source_results: dict[str, list[dict[str, Any]]],
    parent_documents: list[dict[str, Any]],
    source_limit: int,
) -> tuple[dict[str, list[dict[str, Any]]], int]:
    parents = {
        (str(item.get("asset_id") or item.get("id") or ""), str(item.get("version") or "")): item
        for item in parent_documents
        if isinstance(item, dict)
    }
    enriched: dict[str, list[dict[str, Any]]] = {}
    missing = 0
    for source, items in source_results.items():
        output: list[dict[str, Any]] = []
        for item in items[:source_limit]:
            if not isinstance(item, dict):
                continue
            identity = (str(item.get("asset_id") or item.get("id") or ""), str(item.get("version") or ""))
            parent = parents.get(identity)
            if parent is None:
                missing += 1
                continue
            merged = dict(parent)
            for key, value in item.items():
                if key.startswith("_") or key in {"score", "chunk_id", "chunk_ordinal", "lexical_text_redacted"}:
                    merged[key] = value
            output.append(merged)
        enriched[source] = output
    return enriched, missing


def _updated_timestamp(document: dict[str, Any]) -> float:
    text = str(document.get("updated_at") or "").strip()
    if not text:
        return 0.0
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp()
    except (ValueError, OSError):
        return 0.0


def _popularity(document: dict[str, Any], key: str) -> int:
    nested = document.get("popularity") if isinstance(document.get("popularity"), dict) else {}
    try:
        return max(0, int(document.get(f"{key}_count") or nested.get(key) or 0))
    except (TypeError, ValueError):
        return 0


def _find_exact_parents(
    collection: Any,
    base_filter: dict[str, Any],
    exact_keys: list[str],
    exact_terms: list[str],
    source_limit: int,
    query_timeout_ms: int,
) -> list[dict[str, Any]]:
    lanes = (
        {"title_normalized": {"$in": exact_keys}},
        {"aliases_normalized": {"$in": exact_keys}},
        {"asset_id": {"$in": exact_terms}},
    )
    result: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for lane in lanes:
        if not next(iter(lane.values()))["$in"]:
            continue
        cursor = collection.find({"$and": [base_filter, lane]}, {"_id": 0}, max_time_ms=query_timeout_ms)
        cursor = cursor.sort([("asset_id", 1), ("version", 1)]).limit(source_limit)
        for document in cursor:
            identity = (str(document.get("asset_id") or document.get("id") or ""), str(document.get("version") or ""))
            if all(identity) and identity not in seen:
                seen.add(identity)
                result.append(document)
            if len(result) >= source_limit:
                return result
    return result


def _retrieve_from_mongodb(
    *,
    mongodb_uri: str,
    database_name: str,
    chunks_collection: str,
    pointer_collection: str,
    assets_collection: str = "catalog_assets",
    tenant_id: str,
    snapshot_id: str,
    acl: dict[str, Any],
    query_plan: dict[str, Any],
    vectors: dict[str, list[float]],
    query_embedding_contract: dict[str, Any],
    provider_mode: str,
    lexical_index_name: str,
    vector_index_name: str,
    source_limit: int,
    server_selection_timeout_ms: int,
    query_timeout_ms: int,
) -> dict[str, Any]:
    client = MongoClient(
        mongodb_uri,
        serverSelectionTimeoutMS=server_selection_timeout_ms,
        connectTimeoutMS=server_selection_timeout_ms,
        socketTimeoutMS=query_timeout_ms,
        appname="business-work-design-agent-retriever",
    )
    try:
        database = client[database_name]
        pointer = database[pointer_collection].find_one(
            {"tenant_id": tenant_id},
            {"_id": 0, "snapshot_id": 1, "active_snapshot_id": 1, "embedding_contract": 1},
            max_time_ms=query_timeout_ms,
        )
        active_snapshot_id = str((pointer or {}).get("snapshot_id") or (pointer or {}).get("active_snapshot_id") or "")
        if not active_snapshot_id:
            return {"active_snapshot_id": "", "source_results": {}}
        if active_snapshot_id != snapshot_id:
            return {"active_snapshot_id": active_snapshot_id, "source_results": {}}
        active_contract = (pointer or {}).get("embedding_contract") if isinstance((pointer or {}).get("embedding_contract"), dict) else {}
        contract_fields = ("model", "version", "dimension")
        if any(active_contract.get(field) in (None, "") for field in contract_fields):
            return {"active_snapshot_id": active_snapshot_id, "contract_error": "CATALOG_EMBEDDING_CONTRACT_MISSING", "source_results": {}}
        if any(str(active_contract.get(field)) != str(query_embedding_contract.get(field)) for field in contract_fields):
            return {"active_snapshot_id": active_snapshot_id, "contract_error": "QUERY_EMBEDDING_CONTRACT_MISMATCH", "source_results": {}}

        collection = database[chunks_collection]
        parents_collection = database[assets_collection]
        queries = [item for item in query_plan.get("queries", []) if isinstance(item, dict)]
        search_text = " ".join(str(item.get("text") or "") for item in queries if item.get("kind") != "exact")[:4000]
        exact_terms = [str(item.get("text") or "")[:500] for item in queries if item.get("kind") == "exact"]
        exact_keys = [key for key in (_normalize_exact_key(term) for term in exact_terms) if key]
        asset_types = sorted(
            {
                str(asset_type)
                for item in queries
                for asset_type in item.get("expected_asset_types", [])
                if asset_type in {"component", "flow"}
            }
        )
        query_ids = [str(item.get("query_id")) for item in queries if item.get("query_id")]
        base_filter = _mongo_base_filter(tenant_id, snapshot_id, acl, asset_types)
        search_filters = _search_filter_clauses(tenant_id, snapshot_id, acl, asset_types)
        exact_docs: list[dict[str, Any]] = []
        if exact_keys or exact_terms:
            exact_docs = _find_exact_parents(
                parents_collection,
                base_filter,
                exact_keys,
                exact_terms,
                source_limit,
                query_timeout_ms,
            )

        if provider_mode == "application_rrf":
            lexical_docs = list(
                collection.aggregate(
                    [
                        {
                            "$search": {
                                "index": lexical_index_name,
                                "compound": {
                                    "must": [{"text": {"query": search_text, "path": ["title", "description", "lexical_text_redacted", "category"]}}],
                                    "filter": search_filters,
                                },
                            }
                        },
                        {"$limit": source_limit},
                        {"$project": {"_id": 0, "score": {"$meta": "searchScore"}, "asset_id": 1, "version": 1, "asset_type": 1, "title": 1, "description": 1, "category": 1, "readme": 1, "lexical_text_redacted": 1, "technical_contract_status": 1, "ports": 1, "relations": 1, "tenant_id": 1, "snapshot_id": 1, "acl": 1, "stars_count": 1, "downloads_count": 1, "updated_at": 1, "chunk_id": 1}},
                    ],
                    maxTimeMS=query_timeout_ms,
                )
            )
            source_results = {"exact": exact_docs, "lexical": lexical_docs}
            for query_id in query_ids:
                vector_docs = list(
                    collection.aggregate(
                        [
                            {
                                "$vectorSearch": {
                                    "index": vector_index_name,
                                    "path": "embedding.vector",
                                    "queryVector": vectors[query_id],
                                    "numCandidates": min(1000, source_limit * 10),
                                    "limit": source_limit,
                                    "filter": base_filter,
                                }
                            },
                            {"$project": {"_id": 0, "score": {"$meta": "vectorSearchScore"}, "asset_id": 1, "version": 1, "asset_type": 1, "title": 1, "description": 1, "category": 1, "readme": 1, "lexical_text_redacted": 1, "technical_contract_status": 1, "ports": 1, "relations": 1, "tenant_id": 1, "snapshot_id": 1, "acl": 1, "stars_count": 1, "downloads_count": 1, "updated_at": 1, "chunk_id": 1}},
                        ],
                        maxTimeMS=query_timeout_ms,
                    )
                )
                source_results[f"vector:{query_id}"] = vector_docs
        else:
            fusion_operator = "$rankFusion" if provider_mode == "native_rank_fusion" else "$scoreFusion"
            fusion_pipelines: dict[str, list[dict[str, Any]]] = {
                "lexical": [
                    {
                        "$search": {
                            "index": lexical_index_name,
                            "compound": {
                                "must": [{"text": {"query": search_text, "path": ["title", "description", "lexical_text_redacted", "category"]}}],
                                "filter": search_filters,
                            },
                        }
                    },
                    {"$limit": source_limit},
                ]
            }
            native_pipeline_query_ids: dict[str, str] = {}
            native_weights: dict[str, float] = {"lexical": 1.0}
            query_kind_by_id = {
                str(item.get("query_id")): str(item.get("kind") or "")
                for item in queries
                if item.get("query_id")
            }
            for index, query_id in enumerate(query_ids):
                pipeline_name = f"vector_{index:02d}"
                native_pipeline_query_ids[pipeline_name] = query_id
                native_weights[pipeline_name] = QUERY_KIND_WEIGHTS.get(query_kind_by_id.get(query_id, ""), 1.0)
                fusion_pipelines[pipeline_name] = [
                    {
                        "$vectorSearch": {
                            "index": vector_index_name,
                            "path": "embedding.vector",
                            "queryVector": vectors[query_id],
                            "numCandidates": min(1000, source_limit * 10),
                            "limit": source_limit,
                            "filter": base_filter,
                        }
                    }
                ]
            fusion_spec: dict[str, Any] = {
                "input": {"pipelines": fusion_pipelines},
                "combination": {"weights": native_weights},
                "scoreDetails": True,
            }
            if provider_mode == "native_score_fusion":
                fusion_spec["input"]["normalization"] = "none"
                fusion_spec["combination"]["method"] = "avg"
            score_details_meta = "searchScoreDetails" if provider_mode == "native_rank_fusion" else "scoreDetails"
            fused_docs = list(
                collection.aggregate(
                    [
                        {fusion_operator: fusion_spec},
                        {"$addFields": {"_fusion_score_details": {"$meta": score_details_meta}}},
                        {"$limit": source_limit},
                    ],
                    maxTimeMS=query_timeout_ms,
                )
            )
            source_results = {"exact": exact_docs, "native_fused": fused_docs}

        # Search chunks only establish candidate identity and ranking evidence.
        # Re-fetch authoritative parent metadata under the same tenant/snapshot/
        # ACL filter so ports, relations, README, and popularity cannot be lost
        # or forged by a stale/orphan chunk.
        identities = sorted(
            {
                (str(item.get("asset_id") or item.get("id") or ""), str(item.get("version") or ""))
                for items in source_results.values()
                for item in items[:source_limit]
                if isinstance(item, dict)
                and str(item.get("asset_id") or item.get("id") or "")
                and str(item.get("version") or "")
            }
        )
        parent_documents: list[dict[str, Any]] = []
        if identities:
            for offset in range(0, len(identities), 250):
                batch = identities[offset : offset + 250]
                identity_filter = {"$or": [{"asset_id": asset_id, "version": version} for asset_id, version in batch]}
                parent_documents.extend(
                    list(
                        parents_collection.find(
                            {"$and": [base_filter, identity_filter]},
                            {"_id": 0},
                            max_time_ms=query_timeout_ms,
                        )
                    )
                )
        source_results, missing_parent_count = _enrich_source_results(source_results, parent_documents, source_limit)

        # Relation payloads are never trusted as documents. Only parent relation
        # IDs are re-queried from the authoritative asset collection.
        relation_refs: list[tuple[str, str]] = []
        for source_items in source_results.values():
            for document in source_items[:source_limit]:
                for relation in document.get("relations", []) if isinstance(document.get("relations"), list) else []:
                    if not isinstance(relation, dict):
                        continue
                    ref = (str(relation.get("asset_id") or ""), str(relation.get("version") or ""))
                    if all(ref) and ref not in relation_refs:
                        relation_refs.append(ref)
                    if len(relation_refs) >= source_limit:
                        break
        if relation_refs:
            relation_identity = {
                "$or": [{"asset_id": asset_id, "version": version} for asset_id, version in relation_refs]
            }
            source_results["relation"] = list(
                parents_collection.find(
                    {"$and": [base_filter, relation_identity]},
                    {"_id": 0},
                    limit=source_limit,
                    max_time_ms=query_timeout_ms,
                )
            )
        return {
            "active_snapshot_id": active_snapshot_id,
            "source_results": source_results,
            "native_pipeline_query_ids": native_pipeline_query_ids if provider_mode != "application_rrf" else {},
            "missing_parent_count": missing_parent_count,
        }
    finally:
        client.close()


def _rrf(
    source_results: dict[str, list[dict[str, Any]]],
    k: int = 60,
    source_weights: dict[str, float] | None = None,
) -> list[dict[str, Any]]:
    scores: dict[tuple[str, str], float] = {}
    documents: dict[tuple[str, str], dict[str, Any]] = {}
    ranks: dict[tuple[str, str], dict[str, int]] = {}
    for source, items in source_results.items():
        seen_in_source: set[tuple[str, str]] = set()
        for rank, item in enumerate(items[:MAX_SOURCE_CANDIDATES], start=1):
            if not isinstance(item, dict):
                continue
            key = (str(item.get("asset_id") or item.get("id") or ""), str(item.get("version") or ""))
            if not all(key) or key in seen_in_source:
                continue
            seen_in_source.add(key)
            default_weight = 2.0 if source == "exact" else 0.25 if source == "relation" else 1.0
            weight = float((source_weights or {}).get(source, default_weight))
            scores[key] = scores.get(key, 0.0) + weight / (k + rank)
            ranks.setdefault(key, {})[source] = rank
            if key not in documents:
                documents[key] = dict(item)
            elif source == "native_fused" and isinstance(item.get("_fusion_score_details"), dict):
                # exact results are inserted first, but native score details are
                # the authoritative evidence for per-query contribution trace.
                documents[key]["_fusion_score_details"] = dict(item["_fusion_score_details"])
    ordered = sorted(
        scores,
        key=lambda key: (
            -scores[key],
            -_popularity(documents[key], "stars"),
            -_popularity(documents[key], "downloads"),
            -_updated_timestamp(documents[key]),
            key[0],
            key[1],
        ),
    )
    result: list[dict[str, Any]] = []
    for fused_rank, key in enumerate(ordered, start=1):
        item = dict(documents[key])
        item["_fused_score"] = scores[key]
        item["_source_ranks"] = ranks[key]
        item["_fused_rank"] = fused_rank
        result.append(item)
    return result


def _native_vector_contributions(
    document: dict[str, Any], pipeline_query_ids: dict[str, str]
) -> tuple[list[str], dict[str, int | float | str]]:
    score_details = document.get("_fusion_score_details")
    details = score_details.get("details") if isinstance(score_details, dict) else None
    if not isinstance(details, list):
        return [], {}
    matched: list[str] = []
    ranks: dict[str, int | float | str] = {}
    for detail in details:
        if not isinstance(detail, dict):
            continue
        query_id = pipeline_query_ids.get(str(detail.get("inputPipelineName") or ""))
        if not query_id:
            continue
        if query_id not in matched:
            matched.append(query_id)
        rank_or_score = detail.get("rank")
        if rank_or_score in (None, "N/A"):
            rank_or_score = detail.get("inputPipelineRawScore", detail.get("value"))
        if rank_or_score is not None:
            ranks[query_id] = rank_or_score
    return sorted(matched), ranks


def retrieve_catalog_candidates(
    query_plan: Any,
    query_vectors: Any,
    *,
    tenant_id: str = "",
    catalog_snapshot_id: str = "",
    acl_context: Any = None,
    provider_mode: str,
    mongodb_uri: Any,
    database_name: str = "business_work_design",
    chunks_collection: str = "catalog_asset_chunks",
    assets_collection: str = "catalog_assets",
    pointer_collection: str = "catalog_active_pointers",
    lexical_index_name: str = "catalog_lexical",
    vector_index_name: str = "catalog_vector",
    top_n: int = 20,
    source_limit: int = 50,
    server_selection_timeout_ms: int = 5000,
    query_timeout_ms: int = 10000,
) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    plan = _payload(query_plan)
    mode = str(provider_mode or "").strip()
    if mode not in PROVIDER_MODES:
        return _error(trace_id, "UNSUPPORTED_PROVIDER_MODE", "지원되지 않는 provider_mode입니다.")
    if not plan.get("ok"):
        return _error(trace_id, "INVALID_QUERY_PLAN", "성공한 query plan이 필요합니다.")
    tenant = str(plan.get("tenant_id") or "").strip()
    snapshot = str(plan.get("catalog_snapshot_id") or "").strip()
    supplied_tenant = str(tenant_id or "").strip()
    supplied_snapshot = str(catalog_snapshot_id or "").strip()
    if not tenant or not snapshot:
        return _error(trace_id, "CATALOG_SCOPE_MISSING", "query plan에 tenant_id와 catalog_snapshot_id가 필요합니다.")
    if (supplied_tenant and supplied_tenant != tenant) or (supplied_snapshot and supplied_snapshot != snapshot):
        return _error(trace_id, "QUERY_PLAN_SCOPE_MISMATCH", "query plan의 tenant 또는 snapshot 계약이 일치하지 않습니다.")
    plan_acl = plan.get("acl") if isinstance(plan.get("acl"), dict) else {}
    acl = _payload(acl_context) if acl_context is not None else plan_acl
    if not plan_acl.get("subject_id"):
        return _error(trace_id, "ACL_CONTEXT_MISSING", "query plan에 검증 가능한 ACL context가 필요합니다.")
    if str(plan_acl.get("subject_id") or "") != str(acl.get("subject_id") or "") or {
        item.lower() for item in _string_list(plan_acl.get("groups"))
    } != {item.lower() for item in _string_list(acl.get("groups"))}:
        return _error(trace_id, "ACL_CONTEXT_MISMATCH", "query plan을 만든 ACL context와 현재 ACL context가 다릅니다.")
    lock_fields = ("work_definition_id", "work_definition_revision", "approved_hash", "design_scope_sha256")
    if any(plan.get(field) in (None, "") for field in lock_fields) or not str(plan.get("approved_hash")).startswith("sha256:"):
        return _error(trace_id, "QUERY_PLAN_LOCK_MISSING", "query plan에 승인 업무와 design scope lock이 필요합니다.")
    query_plan_hash = str(plan.get("query_plan_sha256") or "")
    plan_core = {
        key: value
        for key, value in plan.items()
        if key not in {"ok", "status", "query_plan_sha256", "trace_id"}
    }
    if (
        not re.fullmatch(r"sha256:[0-9a-fA-F]{64}", query_plan_hash)
        or not hmac.compare_digest(query_plan_hash.lower(), _canonical_hash(plan_core).lower())
    ):
        return _error(trace_id, "QUERY_PLAN_HASH_MISMATCH", "query plan hash가 canonical payload와 일치하지 않습니다.")
    if not isinstance(plan.get("queries"), list) or not plan["queries"]:
        return _error(trace_id, "INVALID_QUERY_PLAN", "검색 query가 없습니다.")
    provider_query_limit = MAX_NATIVE_QUERY_COUNT if mode.startswith("native_") else MAX_QUERY_COUNT
    if len(plan["queries"]) > provider_query_limit:
        return _error(
            trace_id,
            "SEARCH_QUERY_LIMIT_EXCEEDED",
            "선택한 검색 provider가 한 번에 처리할 수 있는 query 수를 초과했습니다.",
            details={"provider_mode": mode, "query_count": len(plan["queries"]), "maximum": provider_query_limit},
        )
    uri = _secret(mongodb_uri)
    if not uri:
        return _error(trace_id, "CATALOG_CONFIGURATION_MISSING", "MongoDB 연결 설정이 필요합니다.")
    vector_payload = _payload(query_vectors)
    if any(str(vector_payload.get(field) or "") != str(plan.get(field) or "") for field in ("design_scope_sha256", "query_plan_sha256")):
        return _error(trace_id, "QUERY_VECTOR_PLAN_MISMATCH", "query vectors가 현재 query plan의 scope/hash lock과 일치하지 않습니다.")
    try:
        vectors, query_embedding_contract = _query_vectors(query_vectors)
    except ValueError as exc:
        code = str(exc)
        messages = {
            "VECTOR_CONTRACT_DIMENSION_INVALID": "query embedding 계약의 dimension이 유효하지 않습니다.",
            "VECTOR_PAYLOAD_INVALID": "query vector payload가 유효하지 않습니다.",
            "VECTOR_NUMERIC_INVALID": "query vector는 bool이 아닌 유한 숫자로만 구성되어야 합니다.",
            "VECTOR_DIMENSION_MISMATCH": "query vector dimension이 계약 또는 다른 vector와 다릅니다.",
        }
        return _error(trace_id, code if code in messages else "VECTOR_PAYLOAD_INVALID", messages.get(code, "query vector가 유효하지 않습니다."))
    query_ids = {str(item.get("query_id")) for item in plan["queries"] if isinstance(item, dict) and item.get("query_id")}
    if len(query_ids) != len(plan["queries"]):
        return _error(trace_id, "INVALID_QUERY_PLAN", "모든 query에는 중복되지 않는 query_id가 필요합니다.")
    if not query_ids or set(vectors) != query_ids:
        return _error(trace_id, "VECTOR_QUERY_MISSING", "모든 query plan ID에 정확히 대응하는 vector가 필요합니다.")
    if any(query_embedding_contract.get(field) in (None, "") for field in ("model", "version", "dimension")):
        return _error(trace_id, "QUERY_EMBEDDING_CONTRACT_MISSING", "query vector의 model, version, dimension 계약이 필요합니다.")

    top_n = max(1, min(50, int(top_n or 20)))
    source_limit = max(top_n, min(MAX_SOURCE_CANDIDATES, int(source_limit or 50)))
    try:
        safe_database_name = _safe_identifier(database_name, "business_work_design")
        safe_chunks_collection = _safe_identifier(chunks_collection, "catalog_asset_chunks")
        safe_assets_collection = _safe_identifier(assets_collection, "catalog_assets")
        safe_pointer_collection = _safe_identifier(pointer_collection, "catalog_active_pointers")
        safe_lexical_index_name = _safe_identifier(lexical_index_name, "catalog_lexical")
        safe_vector_index_name = _safe_identifier(vector_index_name, "catalog_vector")
    except ValueError:
        return _error(trace_id, "INVALID_SEARCH_CONFIGURATION", "database, collection 또는 index 이름 형식이 잘못되었습니다.")
    try:
        backend_result = _retrieve_from_mongodb(
            mongodb_uri=uri,
            database_name=safe_database_name,
            chunks_collection=safe_chunks_collection,
            assets_collection=safe_assets_collection,
            pointer_collection=safe_pointer_collection,
            tenant_id=tenant,
            snapshot_id=snapshot,
            acl=acl,
            query_plan=plan,
            vectors=vectors,
            query_embedding_contract=query_embedding_contract,
            provider_mode=mode,
            lexical_index_name=safe_lexical_index_name,
            vector_index_name=safe_vector_index_name,
            source_limit=source_limit,
            server_selection_timeout_ms=max(1000, min(30000, int(server_selection_timeout_ms or 5000))),
            query_timeout_ms=max(1000, min(60000, int(query_timeout_ms or 10000))),
        )
    except OperationFailure as exc:
        if exc.code == 50:
            return _error(trace_id, "SEARCH_TIMEOUT", "MongoDB 검색 실행 시간이 초과되었습니다.", retryable=True, details={"mongo_code": exc.code})
        return _error(trace_id, "SEARCH_OPERATOR_UNAVAILABLE", "선택한 검색 provider mode를 MongoDB가 실행하지 못했습니다.", retryable=False, details={"provider_mode": mode, "mongo_code": exc.code})
    except (ServerSelectionTimeoutError, ConnectionFailure) as exc:
        return _error(trace_id, "SEARCH_TIMEOUT", "MongoDB 검색 연결 시간이 초과되었습니다.", retryable=True, details={"exception_type": type(exc).__name__})
    except (ConfigurationError, PyMongoError) as exc:
        return _error(trace_id, "SEARCH_PROVIDER_ERROR", "MongoDB 검색 provider 오류가 발생했습니다.", retryable=False, details={"exception_type": type(exc).__name__})

    active_snapshot = str(backend_result.get("active_snapshot_id") or "")
    if not active_snapshot:
        return _error(trace_id, "CATALOG_NOT_READY", "활성 catalog snapshot이 없습니다.")
    if active_snapshot != snapshot:
        return _error(trace_id, "ACTIVE_SNAPSHOT_MISMATCH", "요청 snapshot이 현재 활성 snapshot과 일치하지 않습니다.", details={"requested_snapshot_id": snapshot})
    contract_error = str(backend_result.get("contract_error") or "")
    if contract_error:
        messages = {
            "CATALOG_EMBEDDING_CONTRACT_MISSING": "활성 catalog pointer에 embedding 계약이 없습니다. snapshot을 재검증·재활성화해야 합니다.",
            "QUERY_EMBEDDING_CONTRACT_MISMATCH": "query embedding model/version/dimension이 활성 catalog와 일치하지 않습니다.",
        }
        return _error(trace_id, contract_error, messages.get(contract_error, "embedding 계약이 일치하지 않습니다."))
    source_results = backend_result.get("source_results") if isinstance(backend_result.get("source_results"), dict) else {}
    query_kind_by_id = {
        str(item.get("query_id")): str(item.get("kind") or "")
        for item in plan["queries"]
        if isinstance(item, dict) and item.get("query_id")
    }
    source_weights = {
        f"vector:{query_id}": QUERY_KIND_WEIGHTS.get(kind, 1.0)
        for query_id, kind in query_kind_by_id.items()
    }
    fused = _rrf(
        {key: value for key, value in source_results.items() if isinstance(value, list)},
        source_weights=source_weights,
    )
    if not fused:
        return _error(trace_id, "NO_CANDIDATES", "권한과 검색 조건을 만족하는 catalog 후보가 없습니다.")

    candidates: list[dict[str, Any]] = []
    rejected_counts = {"scope_or_acl": 0, "invalid_identity": 0}
    native_pipeline_query_ids = (
        backend_result.get("native_pipeline_query_ids")
        if isinstance(backend_result.get("native_pipeline_query_ids"), dict)
        else {}
    )
    for item in fused:
        if not _acl_allows(item, tenant, snapshot, acl):
            rejected_counts["scope_or_acl"] += 1
            continue
        ranks = item.get("_source_ranks") if isinstance(item.get("_source_ranks"), dict) else {}
        vector_ranks = {
            source.split(":", 1)[1]: rank
            for source, rank in ranks.items()
            if source.startswith("vector:")
        }
        matched_query_ids = sorted(vector_ranks)
        native_query_ids, native_vector_evidence = _native_vector_contributions(item, native_pipeline_query_ids)
        if native_query_ids:
            matched_query_ids = native_query_ids
        combined_match_sources = [
            source
            for source in ("exact", "lexical", "native_fused", "relation")
            if ranks.get(source) is not None
        ]
        cleaned = _clean_document(item, "fusion", int(item.get("_fused_rank") or 0), matched_query_ids)
        if not cleaned["asset_id"] or not cleaned["version"] or cleaned["asset_type"] not in {"component", "flow"}:
            rejected_counts["invalid_identity"] += 1
            continue
        cleaned["recommendation_status"] = "candidate"
        cleaned["retrieval_trace"] = {
            "exact_rank": ranks.get("exact"),
            "lexical_rank": ranks.get("lexical"),
            "vector_rank": ranks.get("vector") or (min(vector_ranks.values()) if vector_ranks else None),
            "vector_ranks_by_query_id": vector_ranks,
            "native_vector_evidence_by_query_id": native_vector_evidence,
            "native_fused_rank": ranks.get("native_fused"),
            "relation_rank": ranks.get("relation"),
            "combined_match_sources": combined_match_sources,
            "fused_rank": int(item.get("_fused_rank") or 0),
            "fused_score": round(float(item.get("_fused_score") or 0.0), 12),
            "snapshot_id": snapshot,
            "query_ids": matched_query_ids,
        }
        candidates.append(cleaned)
        if len(candidates) >= top_n:
            break
    if not candidates:
        return _error(trace_id, "NO_AUTHORIZED_CANDIDATES", "후보 재검증 후 권한이 확인된 자산이 없습니다.")
    return {
        "ok": True,
        "status": "COMPLETED",
        "tenant_id": tenant,
        "snapshot_id": snapshot,
        "work_definition_id": str(plan["work_definition_id"]),
        "work_definition_revision": plan["work_definition_revision"],
        "approved_hash": str(plan["approved_hash"]),
        "design_scope_sha256": str(plan["design_scope_sha256"]),
        "query_plan_sha256": str(plan.get("query_plan_sha256") or ""),
        "provider_mode": mode,
        "candidates": candidates,
        "retrieval_trace": {
            "tenant_id": tenant,
            "snapshot_id": snapshot,
            "work_definition_id": str(plan["work_definition_id"]),
            "work_definition_revision": plan["work_definition_revision"],
            "approved_hash": str(plan["approved_hash"]),
            "design_scope_sha256": str(plan["design_scope_sha256"]),
            "query_plan_sha256": str(plan.get("query_plan_sha256") or ""),
            "source_counts": {key: len(value) for key, value in source_results.items() if isinstance(value, list)},
            "post_filter_rejected": rejected_counts,
            "returned_count": len(candidates),
            "rrf_k": 60,
            "query_kind_weights": {
                query_id: QUERY_KIND_WEIGHTS.get(kind, 1.0)
                for query_id, kind in sorted(query_kind_by_id.items())
            },
            "silent_fallback_used": False,
            "missing_parent_count": int(backend_result.get("missing_parent_count") or 0),
        },
        "trace_id": trace_id,
    }


def _error(
    trace_id: str,
    code: str,
    message: str,
    *,
    retryable: bool = False,
    details: dict[str, Any] | None = None,
) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": retryable, "details": details or {}},
        "resume": None,
        "trace_id": trace_id,
    }


class CatalogHybridRetrieverComponent(Component):
    display_name = "21 Catalog Hybrid Retriever"
    description = "활성 snapshot에서 tenant/ACL을 적용한 exact, lexical, vector 후보를 명시적 provider mode로 결합합니다."
    icon = "SearchCheck"
    name = "CatalogHybridRetriever"

    inputs = [
        DataInput(name="query_plan", display_name="Search Query Plan", required=True),
        DataInput(name="query_vectors", display_name="Query Vectors", required=True),
        DropdownInput(name="provider_mode", display_name="Provider Mode", options=sorted(PROVIDER_MODES), value="application_rrf"),
        SecretStrInput(name="mongodb_uri", display_name="MongoDB URI", required=True),
        MessageTextInput(name="database_name", display_name="Database", value="business_work_design", advanced=True),
        MessageTextInput(name="chunks_collection", display_name="Chunks Collection", value="catalog_asset_chunks", advanced=True),
        MessageTextInput(name="assets_collection", display_name="Assets Collection", value="catalog_assets", advanced=True),
        MessageTextInput(name="pointer_collection", display_name="Active Pointer Collection", value="catalog_active_pointers", advanced=True),
        MessageTextInput(name="lexical_index_name", display_name="Lexical Index", value="catalog_lexical", advanced=True),
        MessageTextInput(name="vector_index_name", display_name="Vector Index", value="catalog_vector", advanced=True),
        IntInput(name="top_n", display_name="Final Top N", value=20, advanced=True),
        IntInput(name="source_limit", display_name="Per-source Candidate Limit", value=50, advanced=True),
        IntInput(name="server_selection_timeout_ms", display_name="Server Selection Timeout (ms)", value=5000, advanced=True),
        IntInput(name="query_timeout_ms", display_name="Query Timeout (ms)", value=10000, advanced=True),
    ]
    outputs = [Output(name="retrieval_result", display_name="Retrieval Result", method="build_retrieval_result", types=["Data"])]

    def build_retrieval_result(self) -> Data:
        result = retrieve_catalog_candidates(
            self.query_plan,
            self.query_vectors,
            provider_mode=self.provider_mode,
            mongodb_uri=self.mongodb_uri,
            database_name=getattr(self, "database_name", "business_work_design"),
            chunks_collection=getattr(self, "chunks_collection", "catalog_asset_chunks"),
            assets_collection=getattr(self, "assets_collection", "catalog_assets"),
            pointer_collection=getattr(self, "pointer_collection", "catalog_active_pointers"),
            lexical_index_name=getattr(self, "lexical_index_name", "catalog_lexical"),
            vector_index_name=getattr(self, "vector_index_name", "catalog_vector"),
            top_n=getattr(self, "top_n", 20),
            source_limit=getattr(self, "source_limit", 50),
            server_selection_timeout_ms=getattr(self, "server_selection_timeout_ms", 5000),
            query_timeout_ms=getattr(self, "query_timeout_ms", 10000),
        )
        self.status = f"Hybrid retrieval: {result.get('status')} / mode={result.get('provider_mode', self.provider_mode)} / candidates={len(result.get('candidates', []))}"
        return Data(data=result)

from __future__ import annotations

import hashlib
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, IntInput, Output
from lfx.schema import Data


TECHNICAL_STATUSES = {"metadata_only", "ports_extracted", "flow_graph_extracted", "verified_runtime"}
RECOMMENDATION_STATUSES = {"candidate", "recommended", "alternative", "rejected"}
IDENTITY_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$")
SHA256_PATTERN = re.compile(r"^sha256:[0-9a-f]{64}$")


def _canonical_hash(value: Any) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return "sha256:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return data
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _safe_text(value: Any, maximum: int) -> str:
    return re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", str(value or "")).strip()[:maximum]


def _normalize_port(item: Any, index: int, direction: str) -> dict[str, Any] | None:
    if not isinstance(item, dict):
        return None
    port_id = _safe_text(item.get("port_id") or item.get("name") or f"{direction}-{index}", 100)
    if not port_id:
        return None
    cardinality = _safe_text(item.get("cardinality") or "one", 20).lower()
    if cardinality not in {"one", "many"}:
        cardinality = "one"
    return {
        "port_id": port_id,
        "name": _safe_text(item.get("name") or port_id, 100),
        "data_type": _safe_text(item.get("data_type") or item.get("type") or "", 100),
        "semantic_role": _safe_text(item.get("semantic_role"), 100),
        "schema_ref": _safe_text(item.get("schema_ref"), 500),
        "cardinality": cardinality,
        "required": bool(item.get("required", direction == "input")),
        "has_default": bool(item.get("has_default", False)),
        "secret": bool(item.get("secret", False)),
        "permission": _safe_text(item.get("permission"), 200),
        "network_zone": _safe_text(item.get("network_zone"), 100),
        "streaming": bool(item.get("streaming", False)),
    }


def _normalize_port_contract(value: Any) -> dict[str, list[dict[str, Any]]]:
    raw = value if isinstance(value, dict) else {}
    result: dict[str, list[dict[str, Any]]] = {"inputs": [], "outputs": []}
    for key, direction in (("inputs", "input"), ("outputs", "output")):
        items = raw.get(key) if isinstance(raw.get(key), list) else []
        result[key] = [
            port
            for index, item in enumerate(items[:100], start=1)
            if (port := _normalize_port(item, index, direction)) is not None
        ]
    return result


def build_candidate_context(
    retrieval_result: Any,
    *,
    max_items: int = 20,
    per_item_chars: int = 3000,
    total_context_chars: int = 30000,
) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    retrieval = _payload(retrieval_result)
    if retrieval.get("ok") is not True:
        return _error(trace_id, "RETRIEVAL_NOT_READY", "성공한 retrieval_result가 필요합니다.")
    tenant_id = str(retrieval.get("tenant_id") or "")
    snapshot_id = str(retrieval.get("snapshot_id") or "")
    if not IDENTITY_PATTERN.fullmatch(tenant_id) or not IDENTITY_PATTERN.fullmatch(snapshot_id):
        return _error(trace_id, "RETRIEVAL_SCOPE_MISSING", "retrieval_result에 tenant와 snapshot이 없습니다.")
    lock_fields = (
        "work_definition_id", "work_definition_revision", "approved_hash", "design_scope_sha256", "query_plan_sha256"
    )
    if any(retrieval.get(field) in (None, "") for field in lock_fields):
        return _error(trace_id, "RETRIEVAL_LOCK_MISSING", "retrieval_result에 승인 업무와 design scope lock이 없습니다.")
    if (
        not IDENTITY_PATTERN.fullmatch(str(retrieval.get("work_definition_id") or ""))
        or type(retrieval.get("work_definition_revision")) is not int
        or retrieval["work_definition_revision"] < 0
        or any(
            not SHA256_PATTERN.fullmatch(str(retrieval.get(field) or ""))
            for field in ("approved_hash", "design_scope_sha256", "query_plan_sha256")
        )
    ):
        return _error(trace_id, "RETRIEVAL_LOCK_INVALID", "retrieval_result의 provenance lock 형식이 유효하지 않습니다.")
    raw_trace = retrieval.get("retrieval_trace") if isinstance(retrieval.get("retrieval_trace"), dict) else {}
    locked_trace = {
        "tenant_id": tenant_id,
        "snapshot_id": snapshot_id,
        "work_definition_id": str(retrieval["work_definition_id"]),
        "work_definition_revision": retrieval["work_definition_revision"],
        "approved_hash": str(retrieval["approved_hash"]),
        "design_scope_sha256": str(retrieval["design_scope_sha256"]),
        "query_plan_sha256": str(retrieval["query_plan_sha256"]),
    }
    if any(field in raw_trace and raw_trace.get(field) != expected for field, expected in locked_trace.items()):
        return _error(trace_id, "RETRIEVAL_TRACE_LOCK_MISMATCH", "retrieval trace가 승인 검색 범위와 일치하지 않습니다.")
    retrieval_trace = {**raw_trace, **locked_trace}
    candidates = retrieval.get("candidates") if isinstance(retrieval.get("candidates"), list) else []
    if not candidates:
        return _error(trace_id, "NO_CANDIDATES", "context로 만들 catalog 후보가 없습니다.")
    max_items = max(1, min(50, int(max_items or 20)))
    per_item_chars = max(300, min(12000, int(per_item_chars or 3000)))
    total_context_chars = max(per_item_chars, min(100000, int(total_context_chars or 30000)))

    seen: set[tuple[str, str]] = set()
    items: list[dict[str, Any]] = []
    context_blocks: list[str] = []
    used_chars = 0
    dropped = {"duplicate": 0, "invalid": 0, "budget": 0}
    allowlist: list[dict[str, Any]] = []
    for position, raw in enumerate(candidates, start=1):
        if not isinstance(raw, dict):
            dropped["invalid"] += 1
            continue
        asset_id = _safe_text(raw.get("asset_id"), 200)
        version = _safe_text(raw.get("version"), 100)
        asset_type = _safe_text(raw.get("asset_type"), 50)
        key = (asset_id, version)
        if not asset_id or not version or asset_type not in {"component", "flow"}:
            dropped["invalid"] += 1
            continue
        if key in seen:
            dropped["duplicate"] += 1
            continue
        seen.add(key)
        technical_status = str(raw.get("technical_contract_status") or "metadata_only")
        if technical_status not in TECHNICAL_STATUSES:
            technical_status = "metadata_only"
        recommendation_status = str(raw.get("recommendation_status") or "candidate")
        if recommendation_status not in RECOMMENDATION_STATUSES:
            recommendation_status = "candidate"
        description = _safe_text(raw.get("description"), min(1500, per_item_chars))
        readme_budget = max(0, per_item_chars - len(description) - 800)
        readme_excerpt = _safe_text(raw.get("readme"), readme_budget)
        port_contract = _normalize_port_contract(raw.get("ports"))
        port_contract_sha256 = _canonical_hash(port_contract)
        item = {
            "asset_id": asset_id,
            "version": version,
            "asset_type": asset_type,
            "title": _safe_text(raw.get("title"), 400),
            "category": _safe_text(raw.get("category"), 200),
            "description": description,
            "readme_excerpt": readme_excerpt,
            "recommendation_status": recommendation_status,
            "technical_contract_status": technical_status,
            "metadata_only": technical_status == "metadata_only",
            "ports": port_contract,
            "port_contract_sha256": port_contract_sha256,
            "limitations": [
                _safe_text(value, 500)
                for value in (raw.get("limitations") if isinstance(raw.get("limitations"), list) else [])[:10]
            ],
            "retrieval_trace": raw.get("retrieval_trace") if isinstance(raw.get("retrieval_trace"), dict) else {},
        }
        block = json.dumps(item, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        framed = f'<untrusted-catalog-candidate rank="{position}">\n{block}\n</untrusted-catalog-candidate>'
        if len(items) >= max_items or used_chars + len(framed) > total_context_chars:
            dropped["budget"] += 1
            continue
        items.append(item)
        context_blocks.append(framed)
        used_chars += len(framed)
        allowlist.append(
            {
                "asset_id": asset_id,
                "version": version,
                "asset_type": asset_type,
                "technical_contract_status": technical_status,
                "ports": item["ports"],
                "port_contract_sha256": port_contract_sha256,
            }
        )
    if not items:
        return _error(trace_id, "CONTEXT_BUDGET_EXHAUSTED", "제한 안에 포함할 수 있는 유효 후보가 없습니다.")
    allowlist_projection = [
        {
            "asset_id": item["asset_id"],
            "version": item["version"],
            "asset_type": item["asset_type"],
            "technical_contract_status": item["technical_contract_status"],
            "port_contract_sha256": item["port_contract_sha256"],
        }
        for item in allowlist
    ]
    candidate_allowlist_sha256 = _canonical_hash(allowlist_projection)
    retrieval_trace = {
        **retrieval_trace,
        "candidate_allowlist": allowlist_projection,
        "candidate_allowlist_sha256": candidate_allowlist_sha256,
    }
    return {
        "ok": True,
        "status": "COMPLETED",
        "tenant_id": tenant_id,
        "snapshot_id": snapshot_id,
        "work_definition_id": str(retrieval["work_definition_id"]),
        "work_definition_revision": retrieval["work_definition_revision"],
        "approved_hash": str(retrieval["approved_hash"]),
        "design_scope_sha256": str(retrieval["design_scope_sha256"]),
        "query_plan_sha256": str(retrieval.get("query_plan_sha256") or ""),
        "provider_mode": retrieval.get("provider_mode"),
        "candidate_items": items,
        "candidate_allowlist": allowlist,
        "candidate_allowlist_sha256": candidate_allowlist_sha256,
        "untrusted_candidate_context": "\n\n".join(context_blocks),
        "context_char_count": used_chars,
        "limits": {
            "max_items": max_items,
            "per_item_chars": per_item_chars,
            "total_context_chars": total_context_chars,
        },
        "dropped": dropped,
        "retrieval_trace": retrieval_trace,
        "trace_id": trace_id,
    }


def _error(trace_id: str, code: str, message: str) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


class CandidateContextBuilderComponent(Component):
    display_name = "22 Candidate Context Builder"
    description = "검색 후보를 asset/version 기준으로 중복 제거하고 bounded untrusted context와 asset allowlist를 만듭니다."
    icon = "Rows3"
    name = "CandidateContextBuilder"

    inputs = [
        DataInput(name="retrieval_result", display_name="Retrieval Result", required=True),
        IntInput(name="max_items", display_name="Maximum Items", value=20, advanced=True),
        IntInput(name="per_item_chars", display_name="Characters per Item", value=3000, advanced=True),
        IntInput(name="total_context_chars", display_name="Total Context Characters", value=30000, advanced=True),
    ]
    outputs = [Output(name="candidate_context", display_name="Bounded Candidate Context", method="build_context", types=["Data"])]

    def build_context(self) -> Data:
        result = build_candidate_context(
            self.retrieval_result,
            max_items=getattr(self, "max_items", 20),
            per_item_chars=getattr(self, "per_item_chars", 3000),
            total_context_chars=getattr(self, "total_context_chars", 30000),
        )
        self.status = f"Candidate context: {result.get('status')} / items={len(result.get('candidate_items', []))}"
        return Data(data=result)

from __future__ import annotations

import hashlib
import hmac
import json
import re
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, IntInput, Output
from lfx.schema import Data


IMPLEMENTATION_SOURCES = {
    "builtin",
    "catalog_component",
    "catalog_flow",
    "new_standalone_component",
    "companion_service",
    "human_task",
}
TECHNICAL_STATUSES = {"metadata_only", "ports_extracted", "flow_graph_extracted", "verified_runtime"}
PATTERNS = {
    "deterministic_sequential",
    "single_agent_allowlisted_tools",
    "parent_with_child_flows",
    "producer_reviewer",
    "bounded_fan_out",
    "flow_without_agent",
}
LEGACY_PATTERN_ALIASES = {
    "sequential_flow": "deterministic_sequential",
    "single_agent": "single_agent_allowlisted_tools",
    "fan_out_fan_in": "bounded_fan_out",
    "no_agent_flow": "flow_without_agent",
}
NODE_TYPES = {"start", "task", "decision", "human_review", "system_call", "subflow", "end", "exception"}
APPLIED_SKILL_FIELDS = (
    "skill_id",
    "name",
    "version",
    "prompt_sha256",
    "match_reason",
    "target_stage",
    "source_ref",
)
GENERATION_CONTRACT_KEYS = {
    "component_filename",
    "class_name",
    "display_name",
    "responsibility",
    "input_contract",
    "output_contract",
    "secret_inputs",
    "dependencies",
    "timeout_limits",
    "error_codes",
    "deployment_mode",
    "prompt_pack",
}
SECRET_KEY_TOKENS = {
    "apikey",
    "authorization",
    "clientsecret",
    "cookie",
    "credential",
    "password",
    "passwd",
    "privatekey",
    "pwd",
    "session",
    "smsession",
    "secret",
    "token",
}
SECRET_VALUE_PATTERNS = (
    re.compile(r"(?i)\b(?:api[_-]?key|password|passwd|secret|access[_-]?token|client[_-]?secret|authorization|cookie|session)\s*[:=]\s*[\"']?[^\s,;]{8,}"),
    re.compile(r"(?i)\b(?:bearer|basic)\s+\S{8,}"),
    re.compile(r"\bsk-[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"\b[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"[a-zA-Z][a-zA-Z0-9+.-]*://[^/@\s]+:[^/@\s]+@"),
    re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----"),
)


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return data
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _safe(value: Any, maximum: int = 1000) -> str:
    return re.sub(r"[\x00-\x1f]", " ", str(value or "")).strip()[:maximum]


def _optional_safe(value: Any, maximum: int = 1000) -> str | None:
    if value is None:
        return None
    return _safe(value, maximum)


def _secret_key(value: Any) -> bool:
    text = str(value or "").casefold()
    compact = re.sub(r"[^a-z0-9]", "", text)
    parts = {item for item in re.split(r"[^a-z0-9]+", text) if item}
    # Runtime sizing keys such as max_tokens are not credentials.  Credential
    # labels remain fail-closed, including compound keys such as access_token.
    if ("token" in parts and parts & {"max", "limit", "budget", "count"}) or (
        "session" in parts and parts & {"timeout", "ttl"}
    ):
        return False
    if "token" in compact and any(marker in compact for marker in {"maxtoken", "tokenlimit", "tokenbudget", "tokencount"}):
        return False
    if "session" in compact and any(marker in compact for marker in {"sessiontimeout", "sessionttl"}):
        return False
    strong_markers = SECRET_KEY_TOKENS
    return (
        compact in SECRET_KEY_TOKENS
        or bool(parts & {"token", "session", "pwd"})
        or any(marker in compact for marker in strong_markers)
    )


def _secret_material_path(value: Any, path: str = "config") -> str | None:
    if isinstance(value, dict):
        for key, item in value.items():
            key_text = str(key)
            safe_key = (
                key_text
                if re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]{0,63}", key_text) and not _secret_key(key_text)
                else "<field>"
            )
            child_path = f"{path}.{safe_key}"
            if _secret_key(key) and item not in (None, "", False):
                return child_path
            found = _secret_material_path(item, child_path)
            if found:
                return found
    elif isinstance(value, list):
        for index, item in enumerate(value):
            found = _secret_material_path(item, f"{path}[{index}]")
            if found:
                return found
    elif isinstance(value, str):
        text = value.strip()
        if any(pattern.search(text) for pattern in SECRET_VALUE_PATTERNS):
            return path
    return None


def _secret_value_path(value: Any, path: str) -> str | None:
    if isinstance(value, dict):
        for key, item in value.items():
            key_text = str(key)
            safe_key = (
                key_text
                if re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]{0,63}", key_text) and not _secret_key(key_text)
                else "<field>"
            )
            found = _secret_value_path(item, f"{path}.{safe_key}")
            if found:
                return found
    elif isinstance(value, list):
        for index, item in enumerate(value):
            found = _secret_value_path(item, f"{path}[{index}]")
            if found:
                return found
    elif isinstance(value, str) and any(pattern.search(value.strip()) for pattern in SECRET_VALUE_PATTERNS):
        return path
    return None


def _normalize_required_secrets(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    normalized: list[dict[str, Any]] = []
    for item in value[:50]:
        if not isinstance(item, dict):
            continue
        safe_item: dict[str, Any] = {}
        for key in ("name", "ref", "port_id"):
            if key in item:
                safe_item[key] = _safe(item.get(key), 300)
        for key in ("required", "configured"):
            if key in item:
                safe_item[key] = bool(item.get(key))
        if safe_item.get("name") or safe_item.get("ref") or safe_item.get("port_id"):
            normalized.append(safe_item)
    return normalized


def _normalize_problems(value: Any) -> list[Any]:
    source = value if isinstance(value, list) else ([value] if value not in (None, "") else [])
    result: list[Any] = []
    for item in source[:50]:
        if isinstance(item, dict):
            clean = {
                key: _safe(item.get(key), 5_000)
                for key in ("id", "title", "description", "impact", "evidence_ref")
                if item.get(key) not in (None, "")
            }
            if clean:
                result.append(clean)
        else:
            text = _safe(item, 5_000)
            if text:
                result.append(text)
    return result


def _generation_contract_error(value: Any) -> tuple[str, dict[str, Any]] | None:
    if not isinstance(value, dict):
        return "GENERATION_CONTRACT_MISSING", {"missing_fields": sorted(GENERATION_CONTRACT_KEYS)}
    missing = sorted(key for key in GENERATION_CONTRACT_KEYS if key not in value)
    unexpected_count = sum(1 for key in value if key not in GENERATION_CONTRACT_KEYS)
    if missing:
        return "GENERATION_CONTRACT_INCOMPLETE", {"missing_fields": missing}
    if unexpected_count:
        return "GENERATION_CONTRACT_INVALID", {"unexpected_field_count": unexpected_count}
    if not all(isinstance(value.get(key), str) and str(value.get(key)).strip() for key in ("component_filename", "class_name", "display_name", "responsibility", "deployment_mode", "prompt_pack")):
        return "GENERATION_CONTRACT_INVALID", {"reason": "required text fields must be non-empty strings"}
    if not isinstance(value.get("input_contract"), dict) or not value.get("input_contract"):
        return "GENERATION_CONTRACT_INVALID", {"reason": "input_contract must be a non-empty object"}
    if not isinstance(value.get("output_contract"), dict) or not value.get("output_contract"):
        return "GENERATION_CONTRACT_INVALID", {"reason": "output_contract must be a non-empty object"}
    if not isinstance(value.get("secret_inputs"), list) or not isinstance(value.get("dependencies"), list):
        return "GENERATION_CONTRACT_INVALID", {"reason": "secret_inputs and dependencies must be arrays"}
    if len(value["secret_inputs"]) > 50:
        return "GENERATION_CONTRACT_INVALID", {"reason": "secret_inputs exceeds the bounded limit"}
    for index, declaration in enumerate(value["secret_inputs"]):
        if not isinstance(declaration, dict) or set(declaration) - {"name", "ref", "port_id", "required", "configured"}:
            return "GENERATION_CONTRACT_INVALID", {"reason": f"secret_inputs[{index}] must be a declaration-only object"}
        if not any(isinstance(declaration.get(key), str) and declaration.get(key).strip() for key in ("name", "ref", "port_id")):
            return "GENERATION_CONTRACT_INVALID", {"reason": f"secret_inputs[{index}] requires name, ref, or port_id"}
        if any(key in declaration and not isinstance(declaration.get(key), bool) for key in ("required", "configured")):
            return "GENERATION_CONTRACT_INVALID", {"reason": f"secret_inputs[{index}] boolean flags are invalid"}
    if not isinstance(value.get("timeout_limits"), dict) or not value.get("timeout_limits"):
        return "GENERATION_CONTRACT_INVALID", {"reason": "timeout_limits must be a non-empty object"}
    if not isinstance(value.get("error_codes"), list) or not value.get("error_codes"):
        return "GENERATION_CONTRACT_INVALID", {"reason": "error_codes must be a non-empty array"}
    executable_contract = {key: item for key, item in value.items() if key != "secret_inputs"}
    secret_path = _secret_material_path(executable_contract, "generation_contract")
    if secret_path:
        return "BLUEPRINT_SECRET_MATERIAL_DETECTED", {"field": secret_path}
    secret_path = _secret_material_path(value.get("secret_inputs"), "generation_contract.secret_inputs")
    if secret_path:
        return "BLUEPRINT_SECRET_MATERIAL_DETECTED", {"field": secret_path}
    return None


def _canonical_hash(value: Any) -> str:
    text = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(text.encode("utf-8")).hexdigest()


def _design_scope_hash(scope: dict[str, Any]) -> str:
    keys = (
        "schema_version",
        "tenant_id",
        "catalog_snapshot_id",
        "work_definition_id",
        "work_definition_revision",
        "approved_hash",
        "work_definition",
        "acl_context",
        "design_prompt",
    )
    return _canonical_hash({key: scope.get(key) for key in keys})


def _normalize_port(item: Any, index: int, direction: str) -> dict[str, Any] | None:
    if not isinstance(item, dict):
        return None
    port_id = _safe(item.get("port_id") or item.get("name") or f"{direction}-{index}", 100)
    data_type = _safe(item.get("data_type") or item.get("type") or "", 100)
    if not port_id:
        return None
    cardinality = _safe(item.get("cardinality") or "one", 20).lower()
    if cardinality not in {"one", "many"}:
        cardinality = "one"
    return {
        "port_id": port_id,
        "name": _safe(item.get("name") or port_id, 100),
        "data_type": data_type,
        "semantic_role": _safe(item.get("semantic_role"), 100),
        "schema_ref": _safe(item.get("schema_ref"), 500),
        "cardinality": cardinality,
        "required": bool(item.get("required", direction == "input")),
        "has_default": bool(item.get("has_default", False)),
        "secret": bool(item.get("secret", False)),
        "permission": _safe(item.get("permission"), 200),
        "network_zone": _safe(item.get("network_zone"), 100),
        "streaming": bool(item.get("streaming", False)),
    }


def _normalize_port_contract(value: Any) -> dict[str, list[dict[str, Any]]]:
    raw = value if isinstance(value, dict) else {}
    result: dict[str, list[dict[str, Any]]] = {"inputs": [], "outputs": []}
    for key, direction in (("inputs", "input"), ("outputs", "output")):
        items = raw.get(key) if isinstance(raw.get(key), list) else []
        result[key] = [
            port
            for index, item in enumerate(items[:100], start=1)
            if (port := _normalize_port(item, index, direction)) is not None
        ]
    return result


def _project_applied_skill(value: Any) -> dict[str, str] | None:
    if not isinstance(value, dict):
        return None
    projected = {
        "skill_id": _safe(value.get("skill_id"), 128),
        "name": _safe(value.get("name"), 256),
        "version": _safe(value.get("version"), 128),
        "prompt_sha256": str(value.get("prompt_sha256") or ""),
        "match_reason": _safe(value.get("match_reason"), 5_000),
        "target_stage": _safe(value.get("target_stage"), 128),
        "source_ref": str(value.get("source_ref") or ""),
    }
    if (
        any(not projected[field] for field in APPLIED_SKILL_FIELDS)
        or not re.fullmatch(r"sha256:[0-9a-f]{64}", projected["prompt_sha256"])
        or projected["source_ref"] != "approved-skill-registry"
        or _secret_value_path(projected, "applied_skill")
    ):
        return None
    return projected


def normalize_agent_blueprint(
    blueprint_draft: Any,
    work_definition: Any,
    candidate_context: Any,
    applied_skill_context: Any,
    *,
    tenant_id: str,
    catalog_snapshot_id: str,
    max_nodes: int = 300,
    max_edges: int = 600,
) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    draft = _payload(blueprint_draft)
    work = _payload(work_definition)
    candidates = _payload(candidate_context)
    skill_context = _payload(applied_skill_context)
    tenant = _safe(tenant_id, 200)
    snapshot = _safe(catalog_snapshot_id, 200)
    if not tenant or not snapshot:
        return _error(trace_id, "BLUEPRINT_SCOPE_MISSING", "tenant_id와 catalog_snapshot_id가 필요합니다.")
    if not draft:
        return _error(trace_id, "INVALID_BLUEPRINT_DRAFT", "blueprint draft가 비어 있습니다.")
    if draft.get("generation_requests"):
        return _error(
            trace_id,
            "GENERATION_REQUEST_PREMATURE",
            "generation_request는 정규화·검증 뒤 전용 builder가 만드는 사후 산출물입니다.",
        )
    approved_hash = str(work.get("approved_hash") or "")
    state = str(work.get("state") or work.get("status") or "").lower()
    raw_work_revision = work.get("revision") if work.get("revision") is not None else work.get("work_definition_revision")
    if isinstance(raw_work_revision, bool):
        return _error(trace_id, "WORK_DEFINITION_REVISION_INVALID", "승인 업무 정의 revision이 유효하지 않습니다.")
    try:
        work_revision = int(raw_work_revision)
    except (TypeError, ValueError):
        return _error(trace_id, "WORK_DEFINITION_REVISION_INVALID", "승인 업무 정의 revision이 유효하지 않습니다.")
    if work_revision < 0:
        return _error(trace_id, "WORK_DEFINITION_REVISION_INVALID", "승인 업무 정의 revision이 유효하지 않습니다.")
    if state not in {"approved", "active"} or not approved_hash.startswith("sha256:"):
        return _error(trace_id, "WORK_DEFINITION_NOT_APPROVED", "승인 업무 정의와 approved_hash가 필요합니다.")
    if draft.get("approved_hash") and str(draft.get("approved_hash")) != approved_hash:
        return _error(trace_id, "APPROVED_HASH_MISMATCH", "blueprint draft의 approved_hash가 현재 승인본과 다릅니다.")
    if draft.get("catalog_snapshot_id") and str(draft.get("catalog_snapshot_id")) != snapshot:
        return _error(trace_id, "SNAPSHOT_MISMATCH", "blueprint draft의 catalog snapshot이 현재 snapshot과 다릅니다.")
    if candidates.get("tenant_id") != tenant or candidates.get("snapshot_id") != snapshot:
        return _error(trace_id, "CANDIDATE_SCOPE_MISMATCH", "candidate context의 tenant 또는 snapshot이 다릅니다.")

    allowlist_items = candidates.get("candidate_allowlist") if isinstance(candidates.get("candidate_allowlist"), list) else []
    asset_allowlist: dict[tuple[str, str], dict[str, Any]] = {}
    allowlist_projection: list[dict[str, str]] = []
    for item in allowlist_items:
        if not isinstance(item, dict) or set(item) != {
            "asset_id", "version", "asset_type", "technical_contract_status", "ports", "port_contract_sha256"
        }:
            return _error(trace_id, "CANDIDATE_ALLOWLIST_INVALID", "candidate asset 계약 형식이 유효하지 않습니다.")
        asset_id = _safe(item.get("asset_id"), 200)
        version = _safe(item.get("version"), 100)
        asset_type = str(item.get("asset_type") or "")
        status = str(item.get("technical_contract_status") or "")
        port_contract = _normalize_port_contract(item.get("ports"))
        port_contract_sha256 = str(item.get("port_contract_sha256") or "")
        identity = (asset_id, version)
        if (
            not asset_id
            or not version
            or asset_type not in {"component", "flow"}
            or status not in TECHNICAL_STATUSES
            or identity in asset_allowlist
            or not re.fullmatch(r"sha256:[0-9a-f]{64}", port_contract_sha256)
            or not hmac.compare_digest(port_contract_sha256, _canonical_hash(port_contract))
        ):
            return _error(trace_id, "CANDIDATE_ALLOWLIST_INVALID", "candidate asset 또는 port 계약이 유효하지 않습니다.")
        clean_item = {
            "asset_id": asset_id,
            "version": version,
            "asset_type": asset_type,
            "technical_contract_status": status,
            "ports": port_contract,
            "port_contract_sha256": port_contract_sha256,
        }
        asset_allowlist[identity] = clean_item
        allowlist_projection.append({key: clean_item[key] for key in (
            "asset_id", "version", "asset_type", "technical_contract_status", "port_contract_sha256"
        )})
    candidate_allowlist_sha256 = str(candidates.get("candidate_allowlist_sha256") or "")
    if (
        not allowlist_projection
        or not re.fullmatch(r"sha256:[0-9a-f]{64}", candidate_allowlist_sha256)
        or not hmac.compare_digest(candidate_allowlist_sha256, _canonical_hash(allowlist_projection))
    ):
        return _error(trace_id, "CANDIDATE_ALLOWLIST_INVALID", "candidate allowlist hash가 asset/port 계약과 일치하지 않습니다.")

    applied_items = skill_context.get("applied_skills") if isinstance(skill_context.get("applied_skills"), list) else []
    clean_applied_items: list[dict[str, str]] = []
    skill_allowlist: dict[tuple[str, str, str], dict[str, str]] = {}
    for item in applied_items:
        clean_skill = _project_applied_skill(item)
        if clean_skill is None:
            return _error(trace_id, "INVALID_APPLIED_SKILL_CONTEXT", "승인 Skill projection이 유효하지 않습니다.")
        identity = (clean_skill["skill_id"], clean_skill["version"], clean_skill["prompt_sha256"])
        if identity in skill_allowlist:
            return _error(trace_id, "DUPLICATE_SKILL_IDENTITY", "승인 Skill identity가 중복되었습니다.")
        skill_allowlist[identity] = clean_skill
        clean_applied_items.append(clean_skill)
    raw_nodes = draft.get("nodes") if isinstance(draft.get("nodes"), list) else []
    raw_edges = draft.get("edges") if isinstance(draft.get("edges"), list) else []
    max_nodes = max(1, min(500, int(max_nodes or 300)))
    max_edges = max(0, min(1000, int(max_edges or 600)))
    if not raw_nodes or len(raw_nodes) > max_nodes or len(raw_edges) > max_edges:
        return _error(trace_id, "BLUEPRINT_SIZE_INVALID", "node 또는 edge 수가 허용 범위를 벗어났습니다.")

    normalized_nodes: list[dict[str, Any]] = []
    node_ids: set[str] = set()
    for index, raw in enumerate(raw_nodes, start=1):
        if not isinstance(raw, dict):
            return _error(trace_id, "INVALID_BLUEPRINT_NODE", "모든 blueprint node는 object여야 합니다.", details={"index": index})
        node_id = _safe(raw.get("node_id") or raw.get("id"), 100)
        source = str(raw.get("implementation_source") or "").lower()
        node_type = str(raw.get("node_type") or "task").strip().lower()
        if not node_id or node_id in node_ids:
            return _error(trace_id, "DUPLICATE_OR_MISSING_NODE_ID", "node_id가 없거나 중복되었습니다.", details={"index": index})
        if source not in IMPLEMENTATION_SOURCES:
            return _error(trace_id, "INVALID_IMPLEMENTATION_SOURCE", "허용되지 않는 implementation_source입니다.", details={"node_id": node_id})
        if node_type not in NODE_TYPES:
            return _error(
                trace_id,
                "INVALID_NODE_TYPE",
                "허용되지 않는 node_type입니다.",
                details={"node_id": node_id, "allowed": sorted(NODE_TYPES)},
            )
        if bool(raw.get("builtin_satisfies")) and source != "builtin":
            return _error(trace_id, "BUILTIN_PRIORITY_VIOLATION", "built-in으로 충족되는 기능에 다른 구현 출처를 선택할 수 없습니다.", details={"node_id": node_id})
        raw_asset_ref = raw.get("asset_ref") if isinstance(raw.get("asset_ref"), dict) else None
        asset_ref: dict[str, str] | None = None
        port_contract_sha256: str | None = None
        technical_status: str | None = None
        if source in {"catalog_component", "catalog_flow"}:
            key = (str((raw_asset_ref or {}).get("asset_id") or ""), str((raw_asset_ref or {}).get("version") or ""))
            allowed = asset_allowlist.get(key)
            if allowed is None:
                return _error(trace_id, "UNKNOWN_CATALOG_ASSET", "candidate set에 없는 asset ID/version을 참조했습니다.", details={"node_id": node_id})
            expected_type = "component" if source == "catalog_component" else "flow"
            if str(allowed.get("asset_type")) != expected_type:
                return _error(trace_id, "CATALOG_ASSET_TYPE_MISMATCH", "asset type과 implementation_source가 다릅니다.", details={"node_id": node_id})
            technical_status = str(allowed.get("technical_contract_status") or "metadata_only")
            if technical_status not in TECHNICAL_STATUSES:
                technical_status = "metadata_only"
            # Never preserve LLM-supplied extra fields from asset_ref.  The
            # candidate allowlist is the sole authority for catalog identity.
            asset_ref = {"asset_id": allowed["asset_id"], "version": allowed["version"]}
            port_contract_sha256 = str(allowed["port_contract_sha256"])
            # Candidate contract is authoritative; draft ports may not invent a
            # different runtime contract for a catalog asset.
            candidate_ports = allowed.get("ports") if isinstance(allowed.get("ports"), dict) else {}
            raw_input_ports = candidate_ports.get("inputs", [])
            raw_output_ports = candidate_ports.get("outputs", [])
        else:
            asset_ref = None
            raw_input_ports = (
                raw.get("inputs")
                if isinstance(raw.get("inputs"), list)
                else raw.get("input_ports")
                if isinstance(raw.get("input_ports"), list)
                else []
            )
            raw_output_ports = (
                raw.get("outputs")
                if isinstance(raw.get("outputs"), list)
                else raw.get("output_ports")
                if isinstance(raw.get("output_ports"), list)
                else []
            )
        if raw.get("generation_request_ref") or raw.get("generation_request"):
            code = "GENERATION_REQUEST_PREMATURE" if source == "new_standalone_component" else "GENERATION_REQUEST_NOT_ALLOWED"
            return _error(
                trace_id,
                code,
                "generation_request는 정규화·검증 뒤 신규 Standalone node에 대해 전용 builder가 만듭니다.",
                details={"node_id": node_id},
            )
        if source == "new_standalone_component":
            contract_error = _generation_contract_error(raw.get("generation_contract"))
            if contract_error:
                code, details = contract_error
                return _error(trace_id, code, "신규 Standalone Component 생성 계약이 유효하지 않습니다.", details={"node_id": node_id, **details})
            generation_contract = json.loads(json.dumps(raw["generation_contract"], ensure_ascii=False))
        else:
            if raw.get("generation_contract") not in (None, {}):
                return _error(
                    trace_id,
                    "GENERATION_CONTRACT_NOT_ALLOWED",
                    "generation_contract는 신규 Standalone node에만 둘 수 있습니다.",
                    details={"node_id": node_id},
                )
            generation_contract = None

        for field_name in ("title", "responsibility", "reuse_decision_reason", "network_zone", "current_work", "improvement"):
            secret_path = _secret_value_path(raw.get(field_name), f"node[{node_id}].{field_name}")
            if secret_path:
                return _error(
                    trace_id,
                    "BLUEPRINT_SECRET_MATERIAL_DETECTED",
                    "blueprint 자유 서술 필드에는 secret 원문을 넣을 수 없습니다.",
                    details={"node_id": node_id, "field": secret_path},
                )
        for field_name in ("required_permissions", "timeout_policy", "failure_policy", "tests", "problems"):
            secret_path = _secret_material_path(raw.get(field_name), f"node[{node_id}].{field_name}")
            if secret_path:
                return _error(
                    trace_id,
                    "BLUEPRINT_SECRET_MATERIAL_DETECTED",
                    "blueprint 실행·검증 정책에는 secret 원문을 넣을 수 없습니다.",
                    details={"node_id": node_id, "field": secret_path},
                )
        for field_name, field_value in (("inputs", raw_input_ports), ("outputs", raw_output_ports)):
            secret_path = _secret_value_path(field_value, f"node[{node_id}].{field_name}")
            if secret_path:
                return _error(
                    trace_id,
                    "BLUEPRINT_SECRET_MATERIAL_DETECTED",
                    "port 계약에는 secret 원문을 넣을 수 없습니다.",
                    details={"node_id": node_id, "field": secret_path},
                )

        config = raw.get("config") if isinstance(raw.get("config"), dict) else {}
        secret_path = _secret_material_path(config)
        if secret_path:
            return _error(
                trace_id,
                "BLUEPRINT_SECRET_MATERIAL_DETECTED",
                "node config에는 secret 원문을 넣을 수 없습니다. required_secrets의 secret reference를 사용하세요.",
                details={"node_id": node_id, "field": secret_path},
            )

        node_skills: list[dict[str, Any]] = []
        for skill in raw.get("applied_skills", []) if isinstance(raw.get("applied_skills"), list) else []:
            if not isinstance(skill, dict):
                continue
            key = (str(skill.get("skill_id") or ""), str(skill.get("version") or ""), str(skill.get("prompt_sha256") or ""))
            allowed_skill = skill_allowlist.get(key)
            if allowed_skill is None:
                return _error(trace_id, "UNAPPROVED_SKILL_REFERENCE", "승인·적용된 set에 없는 Skill을 참조했습니다.", details={"node_id": node_id})
            node_skills.append({field: allowed_skill[field] for field in APPLIED_SKILL_FIELDS})

        input_ports = [port for idx, item in enumerate(raw_input_ports[:100], start=1) if (port := _normalize_port(item, idx, "input"))]
        output_ports = [port for idx, item in enumerate(raw_output_ports[:100], start=1) if (port := _normalize_port(item, idx, "output"))]
        node = {
            "node_id": node_id,
            "title": _safe(raw.get("title") or raw.get("name") or node_id, 300),
            "node_type": node_type,
            "responsibility": _safe(raw.get("responsibility") or raw.get("description"), 2000),
            "current_work": _safe(raw.get("current_work") or raw.get("as_is"), 20_000),
            "problems": _normalize_problems(raw.get("problems")),
            "improvement": _safe(raw.get("improvement") or raw.get("to_be") or raw.get("responsibility"), 20_000),
            "implementation_source": source,
            "implementation_label": {
                "builtin": "기본 요소",
                "catalog_component": "기존 Component",
                "catalog_flow": "기존 Flow",
                "new_standalone_component": "신규 Custom",
                "companion_service": "외부 서비스",
                "human_task": "Human",
            }[source],
            "reuse_decision_reason": _safe(raw.get("reuse_decision_reason"), 1000),
            "asset_ref": asset_ref,
            "port_contract_sha256": port_contract_sha256,
            "technical_contract_status": technical_status,
            "runtime_validation_status": _safe(raw.get("runtime_validation_status") or "unverified", 50),
            "inputs": input_ports,
            "outputs": output_ports,
            "config": config,
            "required_secrets": _normalize_required_secrets(raw.get("required_secrets")),
            "required_permissions": [item for item in raw.get("required_permissions", [])[:50] if isinstance(item, dict)] if isinstance(raw.get("required_permissions"), list) else [],
            "network_zone": _safe(raw.get("network_zone"), 100),
            "timeout_policy": raw.get("timeout_policy") if isinstance(raw.get("timeout_policy"), dict) else {},
            "failure_policy": raw.get("failure_policy") if isinstance(raw.get("failure_policy"), dict) else {},
            "applied_skills": node_skills,
            "generation_contract": generation_contract,
            "tests": raw.get("tests")[:50] if isinstance(raw.get("tests"), list) else [],
        }
        normalized_nodes.append(node)
        node_ids.add(node_id)

    normalized_edges: list[dict[str, Any]] = []
    edge_ids: set[str] = set()
    for index, raw in enumerate(raw_edges, start=1):
        if not isinstance(raw, dict):
            return _error(trace_id, "INVALID_BLUEPRINT_EDGE", "모든 blueprint edge는 object여야 합니다.", details={"index": index})
        edge_id = _safe(raw.get("edge_id") or raw.get("id") or f"edge-{index}", 100)
        source_node = _safe(raw.get("source_node_id") or raw.get("source"), 100)
        target_node = _safe(raw.get("target_node_id") or raw.get("target"), 100)
        if edge_id in edge_ids or source_node not in node_ids or target_node not in node_ids:
            return _error(trace_id, "DANGLING_OR_DUPLICATE_EDGE", "edge ID가 중복되었거나 node 참조가 없습니다.", details={"edge_id": edge_id})
        for field_name in ("label", "branch_label", "condition", "mapping"):
            secret_path = _secret_material_path(raw.get(field_name), f"edge[{edge_id}].{field_name}")
            if secret_path:
                return _error(
                    trace_id,
                    "BLUEPRINT_SECRET_MATERIAL_DETECTED",
                    "edge 계약에는 secret 원문을 넣을 수 없습니다.",
                    details={"edge_id": edge_id, "field": secret_path},
                )
        normalized_edges.append(
            {
                "edge_id": edge_id,
                "source_node_id": source_node,
                "source_port_id": _safe(raw.get("source_port_id"), 100),
                "target_node_id": target_node,
                "target_port_id": _safe(raw.get("target_port_id"), 100),
                "edge_kind": _safe(raw.get("edge_kind") or "data", 50),
                "label": _safe(raw.get("label") if raw.get("label") is not None else raw.get("branch_label"), 500),
                "branch_label": _safe(raw.get("branch_label") if raw.get("branch_label") is not None else raw.get("label"), 500),
                "condition": _optional_safe(raw.get("condition"), 1000),
                "is_default": bool(raw.get("is_default") if "is_default" in raw else raw.get("default", False)),
                "default": bool(raw.get("default") if "default" in raw else raw.get("is_default", False)),
                "mapping": raw.get("mapping") if isinstance(raw.get("mapping"), dict) else {},
                "connection_validation_status": "unverified",
            }
        )
        edge_ids.add(edge_id)

    pattern = str(draft.get("pattern") or "deterministic_sequential").strip()
    pattern = LEGACY_PATTERN_ALIASES.get(pattern, pattern)
    if pattern not in PATTERNS:
        pattern = "deterministic_sequential"
    for field_name in ("roles", "human_gates", "failure_policy", "observability", "tests", "assumptions", "unresolved"):
        secret_path = _secret_material_path(draft.get(field_name), f"blueprint.{field_name}")
        if secret_path:
            return _error(
                trace_id,
                "BLUEPRINT_SECRET_MATERIAL_DETECTED",
                "blueprint 자유형 section에는 secret 원문을 넣을 수 없습니다.",
                details={"field": secret_path},
            )
    secret_path = _secret_value_path(draft.get("secrets_permissions"), "blueprint.secrets_permissions")
    if secret_path:
        return _error(
            trace_id,
            "BLUEPRINT_SECRET_MATERIAL_DETECTED",
            "secret/permission 선언에는 secret 원문을 넣을 수 없습니다.",
            details={"field": secret_path},
        )
    blueprint_core = {
        "schema_version": "agent-blueprint.v1",
        "tenant_id": tenant,
        "blueprint_id": _safe(draft.get("blueprint_id"), 200)
        or "bp-" + hashlib.sha256(f"{work.get('work_definition_id')}|{approved_hash}|{snapshot}".encode("utf-8")).hexdigest()[:20],
        "work_definition_id": str(work.get("work_definition_id") or ""),
        "work_definition_revision": work_revision,
        "approved_hash": approved_hash,
        "catalog_snapshot_id": snapshot,
        "pattern": pattern,
        "pattern_reason": _safe(draft.get("pattern_reason"), 1000),
        "roles": draft.get("roles")[:100] if isinstance(draft.get("roles"), list) else [],
        "nodes": normalized_nodes,
        "edges": normalized_edges,
        "applied_skills": [
            {field: item[field] for field in APPLIED_SKILL_FIELDS}
            for item in clean_applied_items[:50]
        ],
        "recommended_assets": [
            {key: item[key] for key in (
                "asset_id", "version", "asset_type", "technical_contract_status", "port_contract_sha256"
            )}
            for item in asset_allowlist.values()
        ],
        "generation_requests": [],
        "human_gates": draft.get("human_gates")[:100] if isinstance(draft.get("human_gates"), list) else [],
        "secrets_permissions": draft.get("secrets_permissions")[:200] if isinstance(draft.get("secrets_permissions"), list) else [],
        "failure_policy": draft.get("failure_policy") if isinstance(draft.get("failure_policy"), dict) else {},
        "observability": draft.get("observability") if isinstance(draft.get("observability"), dict) else {},
        "tests": draft.get("tests")[:200] if isinstance(draft.get("tests"), list) else [],
        "assumptions": draft.get("assumptions")[:200] if isinstance(draft.get("assumptions"), list) else [],
        "unresolved": draft.get("unresolved")[:200] if isinstance(draft.get("unresolved"), list) else [],
        "flow_import_verified": False,
        "build_readiness": "design_only",
        "readiness_assessment": {
            "status_axis": "build_readiness",
            "technical_status_axis": "technical_contract_status",
            "connection_status_axis": "connection_validation_status",
            "blockers": [{"code": "PORT_VALIDATION_PENDING", "ref": None}],
            "warnings": [],
            "import_requirements": [{"code": "VERIFY_FLOW_IMPORT", "ref": None}],
            "flow_import_verified": False,
        },
    }
    blueprint_core["to_be_graph"] = {"nodes": [item["node_id"] for item in normalized_nodes], "edges": [item["edge_id"] for item in normalized_edges]}
    return {
        "ok": True,
        "status": "COMPLETED",
        "blueprint": blueprint_core,
        "blueprint_sha256": _canonical_hash(blueprint_core),
        "trace_id": trace_id,
    }


def _error(trace_id: str, code: str, message: str, *, details: dict[str, Any] | None = None) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": details or {}},
        "resume": None,
        "trace_id": trace_id,
    }


def normalize_agent_blueprint_from_scope(
    blueprint_draft: Any,
    design_scope: Any,
    candidate_context: Any,
    applied_skill_context: Any,
    *,
    max_nodes: int = 300,
    max_edges: int = 600,
) -> dict[str, Any]:
    """Normalize only when every downstream artifact has the same scope lock."""
    trace_id = str(uuid.uuid4())
    scope = _payload(design_scope)
    candidates = _payload(candidate_context)
    skills = _payload(applied_skill_context)
    draft = _payload(blueprint_draft)
    required = (
        "tenant_id",
        "catalog_snapshot_id",
        "work_definition_id",
        "work_definition_revision",
        "approved_hash",
        "design_scope_sha256",
        "work_definition",
    )
    supplied_scope_hash = str(scope.get("design_scope_sha256") or "")
    if (
        scope.get("schema_version") != "agent-design-scope/v1"
        or scope.get("ok") is not True
        or any(scope.get(key) in (None, "") for key in required)
        or not re.fullmatch(r"sha256:[0-9a-f]{64}", supplied_scope_hash)
        or not hmac.compare_digest(supplied_scope_hash, _design_scope_hash(scope))
    ):
        return _error(trace_id, "DESIGN_SCOPE_INVALID", "검증·봉인된 design scope가 필요합니다.")
    expected = {
        "tenant_id": str(scope["tenant_id"]),
        "snapshot_id": str(scope["catalog_snapshot_id"]),
        "work_definition_id": str(scope["work_definition_id"]),
        "work_definition_revision": str(scope["work_definition_revision"]),
        "approved_hash": str(scope["approved_hash"]),
        "design_scope_sha256": str(scope["design_scope_sha256"]),
    }
    query_plan_sha256 = str(candidates.get("query_plan_sha256") or "")
    allowlist_items = candidates.get("candidate_allowlist") if isinstance(candidates.get("candidate_allowlist"), list) else []
    allowlist_projection: list[dict[str, str]] = []
    allowlist_valid = bool(allowlist_items)
    seen_allowlist: set[tuple[str, str]] = set()
    for item in allowlist_items:
        if not isinstance(item, dict):
            allowlist_valid = False
            break
        projection = {
            "asset_id": str(item.get("asset_id") or ""),
            "version": str(item.get("version") or ""),
            "asset_type": str(item.get("asset_type") or ""),
            "technical_contract_status": str(item.get("technical_contract_status") or ""),
            "port_contract_sha256": str(item.get("port_contract_sha256") or ""),
        }
        canonical_ports = _normalize_port_contract(item.get("ports"))
        identity = (projection["asset_id"], projection["version"])
        if (
            not projection["asset_id"]
            or not projection["version"]
            or projection["asset_type"] not in {"component", "flow"}
            or projection["technical_contract_status"] not in TECHNICAL_STATUSES
            or not re.fullmatch(r"sha256:[0-9a-f]{64}", projection["port_contract_sha256"])
            or not hmac.compare_digest(projection["port_contract_sha256"], _canonical_hash(canonical_ports))
            or identity in seen_allowlist
        ):
            allowlist_valid = False
            break
        seen_allowlist.add(identity)
        allowlist_projection.append(projection)
    expected_allowlist_sha256 = _canonical_hash(allowlist_projection) if allowlist_valid else ""
    candidate_allowlist_sha256 = str(candidates.get("candidate_allowlist_sha256") or "")
    mismatches: list[str] = []
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", query_plan_sha256):
        mismatches.append("candidate_context.query_plan_sha256")
    if (
        not allowlist_valid
        or not re.fullmatch(r"sha256:[0-9a-f]{64}", candidate_allowlist_sha256)
        or not hmac.compare_digest(candidate_allowlist_sha256, expected_allowlist_sha256)
    ):
        mismatches.append("candidate_context.candidate_allowlist_sha256")
    for label, context in (("candidate_context", candidates), ("skill_context", skills)):
        actual = {
            "tenant_id": str(context.get("tenant_id") or ""),
            "snapshot_id": str(context.get("snapshot_id") or context.get("catalog_snapshot_id") or ""),
            "work_definition_id": str(context.get("work_definition_id") or ""),
            "work_definition_revision": str(context.get("work_definition_revision") if context.get("work_definition_revision") is not None else ""),
            "approved_hash": str(context.get("approved_hash") or ""),
            "design_scope_sha256": str(context.get("design_scope_sha256") or ""),
        }
        mismatches.extend(f"{label}.{key}" for key, value in expected.items() if actual.get(key) != value)
    draft_locks = {
        "snapshot_id": str(draft.get("catalog_snapshot_id") or ""),
        "work_definition_id": str(draft.get("work_definition_id") or ""),
        "work_definition_revision": str(draft.get("work_definition_revision") if draft.get("work_definition_revision") is not None else ""),
        "approved_hash": str(draft.get("approved_hash") or ""),
    }
    mismatches.extend(f"blueprint_draft.{key}" for key in draft_locks if draft_locks[key] != expected[key])
    if mismatches:
        return _error(
            trace_id,
            "DESIGN_CONTEXT_LOCK_MISMATCH",
            "승인 업무, Skill, 검색 후보 또는 blueprint draft의 identity lock이 일치하지 않습니다.",
            details={"fields": sorted(mismatches)},
        )
    result = normalize_agent_blueprint(
        draft,
        scope["work_definition"],
        candidates,
        skills,
        tenant_id=scope["tenant_id"],
        catalog_snapshot_id=scope["catalog_snapshot_id"],
        max_nodes=max_nodes,
        max_edges=max_edges,
    )
    if result.get("ok") is True and isinstance(result.get("blueprint"), dict):
        result["blueprint"]["design_scope_sha256"] = scope["design_scope_sha256"]
        result["blueprint"]["query_plan_sha256"] = query_plan_sha256
        result["blueprint"]["candidate_allowlist_sha256"] = candidate_allowlist_sha256
        result["blueprint_sha256"] = _canonical_hash(result["blueprint"])
    return result


class AgentBlueprintNormalizerComponent(Component):
    display_name = "23 Agent Blueprint Normalizer"
    description = "TO-BE blueprint를 구현 출처와 승인 asset/Skill allowlist에 맞춰 결정론적으로 정규화합니다."
    icon = "Workflow"
    name = "AgentBlueprintNormalizer"

    inputs = [
        DataInput(name="blueprint_draft", display_name="Blueprint Draft", required=True),
        DataInput(name="design_scope", display_name="Sealed Design Scope", required=True),
        DataInput(name="candidate_context", display_name="Verified Candidate Context", required=True),
        DataInput(name="applied_skill_context", display_name="Verified Skill Context", required=True),
        IntInput(name="max_nodes", display_name="Maximum Nodes", value=300, advanced=True),
        IntInput(name="max_edges", display_name="Maximum Edges", value=600, advanced=True),
    ]
    outputs = [Output(name="normalized_blueprint", display_name="Normalized Agent Blueprint", method="build_blueprint", types=["Data"])]

    def build_blueprint(self) -> Data:
        result = normalize_agent_blueprint_from_scope(
            self.blueprint_draft,
            self.design_scope,
            self.candidate_context,
            self.applied_skill_context,
            max_nodes=getattr(self, "max_nodes", 300),
            max_edges=getattr(self, "max_edges", 600),
        )
        node_count = len((result.get("blueprint") or {}).get("nodes", []))
        self.status = f"Blueprint normalize: {result.get('status')} / nodes={node_count}"
        return Data(data=result)

from __future__ import annotations

import json
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


CONNECTION_STATUSES = {"unverified", "contract_compatible", "verified_runtime"}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return data
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _blueprint(value: Any) -> dict[str, Any]:
    payload = _payload(value)
    nested = payload.get("blueprint")
    return nested if isinstance(nested, dict) else payload


def _runtime_evidence(value: Any) -> dict[str, dict[str, Any]]:
    payload = _payload(value)
    items = payload.get("edge_evidence") if isinstance(payload.get("edge_evidence"), list) else []
    return {str(item.get("edge_id")): item for item in items if isinstance(item, dict) and item.get("edge_id")}


def _port_map(node: dict[str, Any], direction: str) -> tuple[dict[str, dict[str, Any]], list[str]]:
    canonical_key = "outputs" if direction == "output" else "inputs"
    legacy_key = "output_ports" if direction == "output" else "input_ports"
    # Agent Blueprint schema names are authoritative.  The legacy aliases are
    # accepted only when the canonical field is absent, never merged, so two
    # conflicting contracts cannot silently coexist.
    raw = (
        node.get(canonical_key)
        if isinstance(node.get(canonical_key), list)
        else node.get(legacy_key)
        if isinstance(node.get(legacy_key), list)
        else []
    )
    result: dict[str, dict[str, Any]] = {}
    duplicates: list[str] = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        port_id = str(item.get("port_id") or item.get("name") or "")
        if not port_id:
            continue
        if port_id in result:
            duplicates.append(port_id)
        result[port_id] = item
    return result, duplicates


def _type_compatible(source: str, target: str) -> bool:
    source_name = source.strip().lower()
    target_name = target.strip().lower()
    if not source_name or not target_name:
        return False
    if source_name == target_name:
        return True
    # Data is the only intentionally broad structured wrapper.  Message and
    # DataFrame are not silently coerced because that needs an explicit adapter.
    return target_name == "data" and source_name in {"data", "json", "dict"}


def validate_port_contracts(normalized_blueprint: Any, runtime_evidence: Any = None) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    blueprint = _blueprint(normalized_blueprint)
    evidence = _runtime_evidence(runtime_evidence)
    if not blueprint or not isinstance(blueprint.get("nodes"), list) or not isinstance(blueprint.get("edges"), list):
        return _error(trace_id, "INVALID_BLUEPRINT", "정규화된 blueprint와 nodes/edges가 필요합니다.")
    approved_hash = str(blueprint.get("approved_hash") or "")
    snapshot_id = str(blueprint.get("catalog_snapshot_id") or "")
    nodes = {str(item.get("node_id")): item for item in blueprint["nodes"] if isinstance(item, dict) and item.get("node_id")}
    node_ports: dict[str, dict[str, dict[str, dict[str, Any]]]] = {}
    issues: list[dict[str, Any]] = []
    for node_id, node in nodes.items():
        inputs, input_duplicates = _port_map(node, "input")
        outputs, output_duplicates = _port_map(node, "output")
        node_ports[node_id] = {"input": inputs, "output": outputs}
        for port_id in input_duplicates + output_duplicates:
            issues.append({"severity": "error", "code": "DUPLICATE_PORT_ID", "node_id": node_id, "port_id": port_id})

    incoming: set[tuple[str, str]] = set()
    validated_edges: list[dict[str, Any]] = []
    for raw in blueprint["edges"]:
        if not isinstance(raw, dict):
            continue
        edge = dict(raw)
        edge_id = str(edge.get("edge_id") or "")
        source_node_id = str(edge.get("source_node_id") or "")
        target_node_id = str(edge.get("target_node_id") or "")
        source_port_id = str(edge.get("source_port_id") or "")
        target_port_id = str(edge.get("target_port_id") or "")
        edge_issues: list[dict[str, Any]] = []
        if source_node_id not in nodes or target_node_id not in nodes:
            edge_issues.append({"code": "DANGLING_NODE_REFERENCE"})
            source_port = target_port = None
        else:
            source_port = node_ports[source_node_id]["output"].get(source_port_id)
            target_port = node_ports[target_node_id]["input"].get(target_port_id)
            if source_port is None:
                edge_issues.append({"code": "SOURCE_PORT_NOT_FOUND"})
            if target_port is None:
                edge_issues.append({"code": "TARGET_PORT_NOT_FOUND"})
        if source_port is not None and target_port is not None:
            if not _type_compatible(str(source_port.get("data_type") or ""), str(target_port.get("data_type") or "")):
                edge_issues.append({"code": "PORT_TYPE_MISMATCH"})
            source_cardinality = str(source_port.get("cardinality") or "one")
            target_cardinality = str(target_port.get("cardinality") or "one")
            if source_cardinality != target_cardinality:
                edge_issues.append({"code": "PORT_CARDINALITY_MISMATCH"})
            source_role = str(source_port.get("semantic_role") or "")
            target_role = str(target_port.get("semantic_role") or "")
            if source_role and target_role and source_role != target_role:
                edge_issues.append({"code": "PORT_SEMANTIC_ROLE_MISMATCH"})
            if bool(source_port.get("streaming")) != bool(target_port.get("streaming")):
                edge_issues.append({"code": "PORT_STREAMING_MISMATCH"})
            if bool(source_port.get("secret")) or bool(target_port.get("secret")):
                if not (bool(source_port.get("secret")) and bool(target_port.get("secret"))):
                    edge_issues.append({"code": "SECRET_PORT_MISMATCH"})
                if not str(target_port.get("permission") or ""):
                    edge_issues.append({"code": "SECRET_PERMISSION_MISSING"})
            source_permission = str(source_port.get("permission") or "")
            target_permission = str(target_port.get("permission") or "")
            if target_permission and source_permission != target_permission:
                edge_issues.append({"code": "PORT_PERMISSION_MISMATCH"})
            source_zone = str(source_port.get("network_zone") or nodes[source_node_id].get("network_zone") or "")
            target_zone = str(target_port.get("network_zone") or nodes[target_node_id].get("network_zone") or "")
            if source_zone and target_zone and source_zone != target_zone and not edge.get("approved_network_bridge_ref"):
                edge_issues.append({"code": "NETWORK_ZONE_MISMATCH"})
            incoming.add((target_node_id, target_port_id))

        compatible = not edge_issues
        status = "contract_compatible" if compatible else "unverified"
        runtime = evidence.get(edge_id)
        if compatible and runtime:
            if (
                runtime.get("status") == "verified_runtime"
                and runtime.get("approved_hash") == approved_hash
                and runtime.get("catalog_snapshot_id") == snapshot_id
                and runtime.get("smoke_test_passed") is True
            ):
                status = "verified_runtime"
            else:
                edge_issues.append({"code": "RUNTIME_EVIDENCE_SCOPE_MISMATCH"})
        edge["connection_validation_status"] = status
        edge["validation_issues"] = [item["code"] for item in edge_issues]
        for issue in edge_issues:
            issues.append({"severity": "error", "edge_id": edge_id, **issue})
        validated_edges.append(edge)

    for node_id, ports in node_ports.items():
        for port_id, port in ports["input"].items():
            if bool(port.get("required")) and not bool(port.get("has_default")) and (node_id, port_id) not in incoming:
                # Explicit secret/config references can satisfy a required port
                # without a normal graph edge.
                node = nodes[node_id]
                configured = port_id in (node.get("config") if isinstance(node.get("config"), dict) else {})
                secret_refs = {
                    str(item.get("port_id") or item.get("name") or "")
                    for item in node.get("required_secrets", [])
                    if isinstance(item, dict) and item.get("configured") is True
                }
                if not configured and port_id not in secret_refs:
                    issues.append({"severity": "error", "code": "REQUIRED_INPUT_UNCONNECTED", "node_id": node_id, "port_id": port_id})

    result_blueprint = dict(blueprint)
    result_blueprint["edges"] = validated_edges
    compatible_count = sum(item.get("connection_validation_status") == "contract_compatible" for item in validated_edges)
    runtime_count = sum(item.get("connection_validation_status") == "verified_runtime" for item in validated_edges)
    unverified_count = sum(item.get("connection_validation_status") == "unverified" for item in validated_edges)
    result_blueprint["connection_validation"] = {
        "status_axis": "connection_validation_status",
        "edge_count": len(validated_edges),
        "contract_compatible_count": compatible_count,
        "verified_runtime_count": runtime_count,
        "unverified_count": unverified_count,
        "error_count": len(issues),
    }
    return {
        "ok": True,
        "status": "COMPLETED_WITH_ISSUES" if issues else "COMPLETED",
        "blueprint": result_blueprint,
        "validation_issues": issues,
        "trace_id": trace_id,
    }


def _error(trace_id: str, code: str, message: str) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


class PortContractValidatorComponent(Component):
    display_name = "24 Port Contract Validator"
    description = "edge의 type, semantic role, cardinality, required, secret, permission, network zone 계약을 검증합니다."
    icon = "Cable"
    name = "PortContractValidator"

    inputs = [
        DataInput(name="normalized_blueprint", display_name="Normalized Blueprint", required=True),
        DataInput(name="runtime_evidence", display_name="Runtime Edge Evidence", required=False, advanced=True),
    ]
    outputs = [Output(name="validated_blueprint", display_name="Port-validated Blueprint", method="build_validated_blueprint", types=["Data"])]

    def build_validated_blueprint(self) -> Data:
        result = validate_port_contracts(self.normalized_blueprint, getattr(self, "runtime_evidence", None))
        summary = (result.get("blueprint") or {}).get("connection_validation", {})
        self.status = f"Port validation: {result.get('status')} / errors={summary.get('error_count', 0)}"
        return Data(data=result)

from __future__ import annotations

import json
import uuid
from typing import Any

from lfx.custom import Component
from lfx.io import DataInput, Output
from lfx.schema import Data


TECHNICAL_STATUSES = {"metadata_only", "ports_extracted", "flow_graph_extracted", "verified_runtime"}
CONNECTION_STATUSES = {"unverified", "contract_compatible", "verified_runtime"}
BUILD_READINESS = {"design_only", "proposed_unverified", "import_ready"}
CATALOG_SOURCES = {"catalog_component", "catalog_flow"}


def _payload(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return value
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        return data
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _blueprint(value: Any) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    payload = _payload(value)
    nested = payload.get("blueprint")
    blueprint = nested if isinstance(nested, dict) else payload
    issues = payload.get("validation_issues") if isinstance(payload.get("validation_issues"), list) else []
    return blueprint, [item for item in issues if isinstance(item, dict)]


def classify_blueprint_readiness(validated_blueprint: Any) -> dict[str, Any]:
    trace_id = str(uuid.uuid4())
    blueprint, validation_issues = _blueprint(validated_blueprint)
    if not blueprint or not isinstance(blueprint.get("nodes"), list) or not isinstance(blueprint.get("edges"), list):
        return _error(trace_id, "INVALID_BLUEPRINT", "port 검증을 거친 blueprint가 필요합니다.")
    approved_hash = str(blueprint.get("approved_hash") or "")
    snapshot_id = str(blueprint.get("catalog_snapshot_id") or "")
    if not approved_hash.startswith("sha256:") or not snapshot_id:
        return _error(trace_id, "BLUEPRINT_LOCK_MISSING", "approved_hash와 catalog_snapshot_id가 필요합니다.")

    blockers: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    import_requirements: list[dict[str, Any]] = []
    for issue in validation_issues:
        if issue.get("severity") == "error":
            blockers.append({"code": str(issue.get("code") or "PORT_VALIDATION_ERROR"), "ref": issue.get("edge_id") or issue.get("node_id")})

    generation_request_refs = {
        str(item.get("node_id") or item.get("target_node_id") or "")
        for item in blueprint.get("generation_requests", [])
        if isinstance(item, dict)
    }
    for node in blueprint["nodes"]:
        if not isinstance(node, dict):
            blockers.append({"code": "INVALID_NODE", "ref": None})
            continue
        node_id = str(node.get("node_id") or "")
        source = str(node.get("implementation_source") or "")
        technical_status = node.get("technical_contract_status")
        if source in CATALOG_SOURCES:
            if technical_status not in TECHNICAL_STATUSES:
                blockers.append({"code": "INVALID_TECHNICAL_CONTRACT_STATUS", "ref": node_id})
            elif technical_status == "metadata_only":
                blockers.append({"code": "METADATA_ONLY_EXECUTION_NODE", "ref": node_id})
            elif technical_status != "verified_runtime":
                warnings.append({"code": "CATALOG_RUNTIME_NOT_VERIFIED", "ref": node_id})
                import_requirements.append({"code": "VERIFY_CATALOG_RUNTIME", "ref": node_id})
        elif technical_status is not None:
            blockers.append({"code": "TECHNICAL_STATUS_ON_NON_CATALOG_NODE", "ref": node_id})

        runtime_status = str(node.get("runtime_validation_status") or "unverified")
        if source in {"builtin", "new_standalone_component"} and runtime_status != "verified_runtime":
            warnings.append({"code": "NODE_RUNTIME_NOT_VERIFIED", "ref": node_id})
            import_requirements.append({"code": "VERIFY_NODE_RUNTIME", "ref": node_id})
        if source == "new_standalone_component":
            has_contract = isinstance(node.get("generation_contract"), dict) and bool(node.get("generation_contract"))
            has_request = bool(node.get("generation_request_ref")) or node_id in generation_request_refs
            if not has_contract:
                blockers.append({"code": "GENERATION_CONTRACT_MISSING", "ref": node_id})
            if not has_request:
                warnings.append({"code": "GENERATION_REQUEST_PENDING", "ref": node_id})
                import_requirements.append({"code": "BUILD_STANDALONE_COMPONENT", "ref": node_id})
        if source == "companion_service" and str(node.get("service_contract_status") or "unverified") != "verified_runtime":
            warnings.append({"code": "COMPANION_SERVICE_NOT_VERIFIED", "ref": node_id})
            import_requirements.append({"code": "VERIFY_COMPANION_SERVICE", "ref": node_id})

        for secret in node.get("required_secrets", []) if isinstance(node.get("required_secrets"), list) else []:
            if isinstance(secret, dict) and secret.get("required", True) and secret.get("configured") is not True:
                warnings.append({"code": "SECRET_NOT_CONFIGURED", "ref": f"{node_id}:{secret.get('name') or secret.get('port_id')}"})
                import_requirements.append({"code": "CONFIGURE_SECRET", "ref": node_id})
        for permission in node.get("required_permissions", []) if isinstance(node.get("required_permissions"), list) else []:
            if isinstance(permission, dict) and permission.get("required", True) and permission.get("granted") is not True:
                warnings.append({"code": "PERMISSION_NOT_GRANTED", "ref": f"{node_id}:{permission.get('name')}"})
                import_requirements.append({"code": "GRANT_PERMISSION", "ref": node_id})

    for edge in blueprint["edges"]:
        if not isinstance(edge, dict):
            blockers.append({"code": "INVALID_EDGE", "ref": None})
            continue
        edge_id = str(edge.get("edge_id") or "")
        connection_status = edge.get("connection_validation_status")
        if connection_status not in CONNECTION_STATUSES:
            blockers.append({"code": "INVALID_CONNECTION_VALIDATION_STATUS", "ref": edge_id})
        elif connection_status == "unverified":
            blockers.append({"code": "EDGE_CONTRACT_INVALID_OR_UNKNOWN", "ref": edge_id})
        elif connection_status == "contract_compatible":
            warnings.append({"code": "EDGE_RUNTIME_NOT_VERIFIED", "ref": edge_id})
            import_requirements.append({"code": "VERIFY_EDGE_RUNTIME", "ref": edge_id})

    unresolved = blueprint.get("unresolved") if isinstance(blueprint.get("unresolved"), list) else []
    for item in unresolved:
        if isinstance(item, dict) and item.get("blocking", True):
            blockers.append({"code": "UNRESOLVED_BLOCKING_ITEM", "ref": item.get("path") or item.get("id")})
        elif item:
            warnings.append({"code": "UNRESOLVED_NONBLOCKING_ITEM", "ref": str(item)[:200]})

    all_edges_runtime = all(
        isinstance(edge, dict) and edge.get("connection_validation_status") == "verified_runtime" for edge in blueprint["edges"]
    )
    all_runtime_requirements_met = not import_requirements
    flow_import_verified = blueprint.get("flow_import_verified") is True
    if blockers:
        readiness = "design_only"
    elif all_edges_runtime and all_runtime_requirements_met and flow_import_verified:
        readiness = "import_ready"
    else:
        readiness = "proposed_unverified"
        if not flow_import_verified:
            import_requirements.append({"code": "VERIFY_FLOW_IMPORT", "ref": blueprint.get("blueprint_id")})

    result_blueprint = dict(blueprint)
    result_blueprint["build_readiness"] = readiness
    result_blueprint["readiness_assessment"] = {
        "status_axis": "build_readiness",
        "technical_status_axis": "technical_contract_status",
        "connection_status_axis": "connection_validation_status",
        "blockers": blockers,
        "warnings": warnings,
        "import_requirements": _dedupe(import_requirements),
        "flow_import_verified": flow_import_verified,
    }
    return {
        "ok": True,
        "status": "COMPLETED",
        "blueprint": result_blueprint,
        "build_readiness": readiness,
        "blockers": blockers,
        "warnings": warnings,
        "trace_id": trace_id,
    }


def _dedupe(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    seen: set[tuple[str, str]] = set()
    result: list[dict[str, Any]] = []
    for item in items:
        key = (str(item.get("code")), str(item.get("ref")))
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result


def _error(trace_id: str, code: str, message: str) -> dict[str, Any]:
    return {
        "ok": False,
        "status": "BLOCKED",
        "artifact_refs": [],
        "error": {"code": code, "message": message, "retryable": False, "details": {}},
        "resume": None,
        "trace_id": trace_id,
    }


